import sys

def solve():
    input = sys.stdin.readline
    N, Q = map(int, input().split())
    A = list(map(int, input().split()))

    elements = sorted([(A[j], j) for j in range(N)])

    queries = []
    for i in range(Q):
        r, x = map(int, input().split())
        queries.append((x, r - 1, i))
    queries.sort()

    size = N
    bit = [0] * (size + 1)

    def update(i, val):
        while i <= size:
            if val > bit[i]:
                bit[i] = val
            i += i & (-i)

    def query(i):
        res = 0
        while i > 0:
            if bit[i] > res:
                res = bit[i]
            i -= i & (-i)
        return res

    elem_idx = 0
    results = [0] * Q

    for x, r, idx in queries:
        while elem_idx < N and elements[elem_idx][0] <= x:
            start = elem_idx
            while elem_idx < N and elements[elem_idx][0] == elements[start][0]:
                elem_idx += 1
            updates = []
            for k in range(start, elem_idx):
                val, pos = elements[k]
                if pos == 0:
                    lis_val = 1
                else:
                    lis_val = 1 + query(pos)
                updates.append((pos, lis_val))
            for pos, lis_val in updates:
                update(pos + 1, lis_val)

        results[idx] = query(r + 1)

    print('\n'.join(map(str, results)))

