    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if n == 1:
            return 0

        weights = sorted(set(w for _, _, w in edges))

        def feasible(W):
            SRC = 2 * n
            SNK = 2 * n + 1
            total_nodes = 2 * n + 2

            adj = [[] for _ in range(total_nodes)]

            def add_edge(u, v, cap):
                adj[u].append([v, cap, len(adj[v])])
                adj[v].append([u, 0, len(adj[u]) - 1])

            for v in range(1, n):
                add_edge(2 * v, 2 * v + 1, threshold)
            for v in range(1, n):
                add_edge(SRC, 2 * v, 1)
            add_edge(0, SNK, n)
            for u, v, w in edges:
                if w <= W:
                    add_edge(2 * u + 1, 2 * v, n)

            from collections import deque
            flow = 0

            while flow < n - 1:
                level = [-1] * total_nodes
                level[SRC] = 0
                q = deque([SRC])
                while q:
                    u = q.popleft()
                    for e in adj[u]:
                        if e[1] > 0 and level[e[0]] == -1:
                            level[e[0]] = level[u] + 1
                            q.append(e[0])
                if level[SNK] == -1:
                    break
                it = [0] * total_nodes

                import sys
                sys.setrecursionlimit(300000)

                def dfs(u, f):
                    if u == SNK:
                        return f
                    for i in range(it[u], len(adj[u])):
                        it[u] = i
                        e = adj[u][i]
                        v, cap, rev = e
                        if cap > 0 and level[u] < level[v]:
                            d = dfs(v, min(f, cap))
                            if d > 0:
                                e[1] -= d
                                adj[v][rev][1] += d
                                return d
                    return 0

                while flow < n - 1:
                    f = dfs(SRC, n)
                    if f == 0:
                        break
                    flow += f

            return flow >= n - 1

        max_w = max(weights) if weights else 0
        if not feasible(max_w):
            return -1

        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(weights[mid]):
                hi = mid
            else:
                lo = mid + 1

        return weights[lo]

