class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can_achieve(x):
            # req[i] = minimum visits needed at position i
            req = [0] * n
            for i in range(n):
                req[i] = (x + points[i] - 1) // points[i]

            # Find rightmost position that needs visits
            R = -1
            for i in range(n - 1, -1, -1):
                if req[i] > 0:
                    R = i
                    break

            if R == -1:
                return True  # no visits needed, 0 moves suffice

            # We need at least R+1 moves to reach position R from start (position 0)
            # The formula: min moves = 2*(R-1) + max over T in [0,R] of:
            #   if T == R: 2*req[R] - 1
            #   if T < R:  (R - T) + 2*max(req[T+1..R]) - 1
            # Base cost of reaching R and coming back is 2*(R-1)
            # Total = 2*(R-1) + extra

            if R == 0:
                return 1 <= m  # just need to be at 0, which takes 1 move

            base = 2 * (R - 1)

            # Compute suffix max of req from position i to R
            suffix_max = [0] * (R + 1)
            suffix_max[R] = req[R]
            for i in range(R - 1, -1, -1):
                suffix_max[i] = max(req[i], suffix_max[i + 1])

            extra = 0
            for T in range(R + 1):
                if T == R:
                    val = 2 * req[R] - 1
                else:
                    val = (R - T) + 2 * suffix_max[T + 1] - 1
                extra = max(extra, val)

            total_moves = base + extra
            return total_moves <= m

        lo, hi = 0, max(points) * (m + 1)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_achieve(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

