                for i in range(1, R):
                    d_prev = 1 if i <= E else 0
                    li = req[i] - prev - d_prev
                    if li < 0:
                        li = 0
                    total_l += li
                    prev = li
                if R == 0:
                    if req[0] > 1:
                        ok = False
                else:
                    d_Rm1 = 1 if (R - 1) < E else 0
                    if prev + d_Rm1 < req[R]:
                        ok = False
                if ok:
                    total_moves = 1 + 2 * total_l + E
                    if total_moves < best:
                        best = total_moves
            return best <= m

        lo, hi = 0, max(points) * m + 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        import math
        n = len(points)

        def can(target):
            # Compute visits needed for each index
            need = [math.ceil(target / points[i]) for i in range(n)]
            # Find rightmost index with need > 0
            r = -1
            for i in range(n):
                if need[i] > 0:
                    r = i
                else:
                    break
            if r == -1:
                return True  # target is 0, always possible

            # Initial trip from -1 to r costs r+1 steps
            cost = r + 1
            if cost > m:
                return False

            # Compute S array greedily
            # S[i] = max(S[i-1], need[i]-1-S[i-1]) for i < r
            # S[r-1] >= need[r]-1
            S = [0] * r
            for i in range(r):
                S[i] = max(S[i-1] if i > 0 else 0, need[i] - 1 - (S[i-1] if i > 0 else 0))

            # Apply final constraint
            if S[r-1] < need[r] - 1:
                S[r-1] = need[r] - 1
                for i in range(r - 2, -1, -1):
                    if S[i] > S[i+1]:
                        S[i] = S[i+1]
                    else:
                        break

            cost += 2 * sum(S)
            return cost <= m

        lo, hi = 0, 10**6
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can_achieve(x):
            if x == 0:
                return True
            v = [0] * n
            for i in range(n):
                v[i] = (x + points[i] - 1) // points[i]

            r = -1
            for i in range(n - 1, -1, -1):
                if v[i] > 0:
                    r = i
                    break
            if r == -1:
                return True

            need = [v[i] - 1 for i in range(r + 1)]
            max_need = max(need)

            if max_need == 0:
                return (r + 1) <= m

            left = [r + 1] * (max_need + 1)
            for i in range(r + 1):
                ni = need[i]
                if ni > 0:
                    k = 1
                    while k <= ni and left[k] == r + 1:
                        left[k] = i
                        k += 1

            total = r + 1
            for k in range(1, max_need):
                total += 2 * (r - left[k])
            total += (r - left[max_need])

            return total <= m

        lo, hi = 0, 10**15
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_achieve(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target):
            if target == 0:
                return True
            # Compute required visits for each position
            need = [0] * n
            for i in range(n):
                need[i] = (target + points[i] - 1) // points[i]

            # Find rightmost position that needs visits
            R = -1
            for i in range(n - 1, -1, -1):
                if need[i] > 0:
                    R = i
                    break

            if R == -1:
                return True

            # cost_right: extra forward sweeps (each gives +1 visit to all positions 0..R)
            max_need_forward = 0
            for i in range(R + 1):
                val = need[i] - 1
                if val > max_need_forward:
                    max_need_forward = val
            cost_right = max(0, max_need_forward)

            # need_back: after initial sweep + cost_right extra forward sweeps,
            # position R has (1 + cost_right) visits. If need[R] > that, must go back.
            need_back = max(0, need[R] - 1 - cost_right)

            # cost_left: extra backward sweeps (each gives +1 visit to all positions 0..R-1)
            # After initial + cost_right forward + need_back backward:
            #   position i < R has (1 + cost_right + need_back) visits
            #   position R has (1 + cost_right) visits
            max_need_backward = 0
            for i in range(R):
                val = need[i] - 1 - cost_right - need_back
                if val > max_need_backward:
                    max_need_backward = val
            cost_left = max(0, max_need_backward)

            total = R
            if need_back > 0:
                total += R
            total += (cost_right + cost_left) * R

            return 1 + total <= m

        lo, hi = 0, 10**15
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can_achieve(mid):
            if mid == 0:
                return True
            # Calculate needed visits for each position
            # Find the rightmost position that needs visits
            right = -1
            for i in range(n):
                if (mid + points[i] - 1) // points[i] > 0:
                    right = i
            if right == -1:
                return True

            # Calculate minimum steps needed
            # Initial sweep from -1 to 'right' takes right+1 steps
            # Each position i gets 1 visit from the sweep
            # Extra visits needed: for i < right, each extra needs a round trip (2 steps each)
            # For i == right, each extra needs 1 step (go left and come back, but only the left part counts as extra visit)
            # Actually: total = right + 1 + 2 * sum(extra[i] for i in 0..right-1) + extra[right]
            extra_sum = 0
            for i in range(right):
                need_i = (mid + points[i] - 1) // points[i]
                if need_i > 1:
                    extra_sum += need_i - 1

            need_right = (mid + points[right] - 1) // points[right]
            extra_right = max(0, need_right - 1)

            total_steps = right + 1 + 2 * extra_sum + extra_right
            return total_steps <= m

        # Binary search on the answer
        lo, hi = 0, 10**15
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_achieve(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

