class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n):
            if n <= 0:
                return 0
            digits = [int(d) for d in str(n)]

            @lru_cache(maxsize=None)
            def dp(pos, tight, sum_so_far, a, b, c, d, started, has_zero):
                if pos == len(digits):
                    if not started:
                        return 0
                    if has_zero:
                        return 1
                    if sum_so_far == 0:
                        return 0
                    product = (2**a) * (3**b) * (5**c) * (7**d)
                    return 1 if product % sum_so_far == 0 else 0

                upper = digits[pos] if tight else 9
                total = 0
                for digit in range(upper + 1):
                    new_tight = 1 if (tight and digit == upper) else 0
                    if not started:
                        if digit == 0:
                            total += dp(pos + 1, new_tight, 0, 0, 0, 0, 0, False, False)
                        else:
                            na, nb, nc, nd = 0, 0, 0, 0
                            if digit == 2: na = 1
                            elif digit == 3: nb = 1
                            elif digit == 4: na = 2
                            elif digit == 5: nc = 1
                            elif digit == 6: na, nb = 1, 1
                            elif digit == 7: nd = 1
                            elif digit == 8: na = 3
                            elif digit == 9: nb = 2
                            total += dp(pos + 1, new_tight, digit, na, nb, nc, nd, True, False)
                    else:
                        if digit == 0:
                            total += dp(pos + 1, new_tight, sum_so_far, a, b, c, d, True, True)
                        else:
                            na, nb, nc, nd = a, b, c, d
                            if digit == 2: na += 1
                            elif digit == 3: nb += 1
                            elif digit == 4: na += 2
                            elif digit == 5: nc += 1
                            elif digit == 6: na, nb = na + 1, nb + 1
                            elif digit == 7: nd += 1
                            elif digit == 8: na += 3
                            elif digit == 9: nb += 2
                            total += dp(pos + 1, new_tight, sum_so_far + digit, na, nb, nc, nd, True, False)
                return total

            return dp(0, 1, 0, 0, 0, 0, 0, False, False)

        return count(r) - count(l - 1)

