from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    M = int(input_data[1])
    S = input_data[2]

    MOD = 998244353
    letters = [chr(ord('a') + i) for i in range(26)]

    def transition(state, c):
        old = [0] * (N + 1)
        for i in range(N):
            old[i + 1] = old[i] + state[i]
        new = [0] * (N + 1)
        for i in range(1, N + 1):
            if S[i - 1] == c:
                new[i] = old[i - 1] + 1
            else:
                new[i] = max(new[i - 1], old[i])
        return tuple(new[i] - new[i - 1] for i in range(1, N + 1))

    init_state = tuple([0] * N)
    dp = {init_state: 1}

    for _ in range(M):
        new_dp = defaultdict(int)
        for state, count in dp.items():
            for c in letters:
                ns = transition(state, c)
                new_dp[ns] = (new_dp[ns] + count) % MOD
        dp = dict(new_dp)

    ans = [0] * (N + 1)
    for state, count in dp.items():
        k = sum(state)
        ans[k] = (ans[k] + count) % MOD

    print(' '.join(map(str, ans)))

