MOD = 998244353

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    S = list(map(ord, input().strip().encode()))

    size = 1 << N

    # d[i] = number of 1-bits among the first i bits
    rows = []
    for mask in range(size):
        d = [0] * (N + 1)
        for i in range(1, N + 1):
            d[i] = d[i - 1] + ((mask >> (i - 1)) & 1)
        rows.append(d)

    def next_state(mask, ch):
        d = rows[mask]
        nm = 0
        prev = 0
        for i in range(1, N + 1):
            val = d[i] if d[i] > prev else prev
            if S[i - 1] == ch:
                cand = d[i - 1] + 1
                if cand > val:
                    val = cand
            if val != prev:
                nm |= 1 << (i - 1)
            prev = val
        return nm

    transitions = [[] for _ in range(size)]
    for mask in range(size):
        cnt = {}
        for c in range(97, 123):  # 'a' .. 'z'
            ns = next_state(mask, c)
            cnt[ns] = cnt.get(ns, 0) + 1
        transitions[mask] = list(cnt.items())

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val:
                for ns, times in transitions[mask]:
                    ndp[ns] = (ndp[ns] + val * times) % MOD
        dp = ndp

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        k = mask.bit_count()
        ans[k] = (ans[k] + val) % MOD

    print(" ".join(map(str, ans)))

