def solve():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    M = int(input_data[1])
    S = input_data[2]

    MOD = 998244353
    num_states = 1 << N

    # Precompute transitions
    def get_v(state):
        v = [0] * (N + 1)
        for i in range(1, N + 1):
            v[i] = v[i-1] + ((state >> (i-1)) & 1)
        return v

    trans = [[0] * 26 for _ in range(num_states)]
    for state in range(num_states):
        v = get_v(state)
        for c_idx in range(26):
            c = chr(ord('a') + c_idx)
            new_v = [0] * (N + 1)
            for i in range(1, N + 1):
                if S[i-1] == c:
                    new_v[i] = v[i-1] + 1
                else:
                    new_v[i] = max(v[i], new_v[i-1])
            new_state = 0
            for i in range(1, N + 1):
                if new_v[i] - new_v[i-1] == 1:
                    new_state |= (1 << (i-1))
            trans[state][c_idx] = new_state

    # DP
    dp = [0] * num_states
    dp[0] = 1

    for _ in range(M):
        new_dp = [0] * num_states
        for state in range(num_states):
            if dp[state] == 0:
                continue
            cnt = dp[state]
            for c_idx in range(26):
                ns = trans[state][c_idx]
                new_dp[ns] = (new_dp[ns] + cnt) % MOD
        dp = new_dp

    # Compute answers
    ans = [0] * (N + 1)
    for state in range(num_states):
        k = bin(state).count('1')
        ans[k] = (ans[k] + dp[state]) % MOD

    print(' '.join(map(str, ans)))

