from sys import stdin

def solve():
    input = stdin.readline
    N, M = map(int, input().split())

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N
    components = []

    for i in range(N):
        if color[i] != -1:
            continue
        color[i] = 0
        side0 = [i]
        side1 = []
        queue = [i]
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    if color[v] == 0:
                        side0.append(v)
                    else:
                        side1.append(v)
                    queue.append(v)
        a, b = len(side0), len(side1)
        e = 0
        for u in side0:
            for v in adj[u]:
                if color[v] == 1:
                    e += 1
        components.append((a, b, e))

    internal = 0
    for a, b, e in components:
        internal ^= (a * b - e) & 1

    pairs = []
    for a, b, _ in components:
        pairs.append((min(a, b), max(a, b)))
    pairs.sort()

    n = len(pairs)
    if n == 0:
        external = 0
    else:
        dp = [0] * (n + 1)
        i = n - 1
        while i >= 0:
            mn = pairs[i][0]
            j = i
            while j >= 0 and pairs[j][0] == mn:
                j -= 1
            group = list(range(j + 1, i + 1))
            group.sort(key=lambda idx: -pairs[idx][1])

            sg_vals = [0] * len(group)
            for k in range(len(group) - 1, -1, -1):
                if k == len(group) - 1:
                    nxt = dp[i + 1]
                else:
                    nxt = sg_vals[k + 1]
                reachable = {nxt, abs(nxt - mn)}
                mex = 0
                while mex in reachable:
                    mex += 1
                sg_vals[k] = mex

            for k in range(len(group)):
                dp[group[k]] = sg_vals[k]

            i = j
        external = dp[0]

    if (internal ^ external) != 0:
        print("Aoki")
    else:
        print("Takahashi")

