class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        def perim_pos(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:
                return 3 * side + (side - y)

        def pos_to_xy(p):
            p %= (4 * side)
            if p <= side:
                return (p, 0)
            elif p <= 2 * side:
                return (side, p - side)
            elif p <= 3 * side:
                return (side - (p - 2 * side), side)
            else:
                return (0, side - (p - 3 * side))

        def manhattan(p1, p2):
            x1, y1 = pos_to_xy(p1)
            x2, y2 = pos_to_xy(p2)
            return abs(x1 - x2) + abs(y1 - y2)

        positions = sorted(perim_pos(x, y) for x, y in points)
        perimeter = 4 * side
        m = n

        def feasible(d):
            if d <= 0:
                return True

            # For each point i, find the rightmost point j (circularly, going clockwise)
            # such that perim_dist(i, j) < d. All points between i and j (clockwise) 
            # definitely conflict with i.
            # Then the first candidate after j needs manhattan check.

            # Precompute conflict extent: for each i, the farthest clockwise point
            # that definitely conflicts (perim dist < d)
            # Use two pointers

            # Unroll: work with indices 0..2m-1 where position[i+m] = position[i] + perimeter
            ext_pos = positions + [p + perimeter for p in positions]

            # right_conflict[i] = largest j > i such that ext_pos[j] - ext_pos[i] < d
            right_conflict = [0] * (2 * m)
            j = 0
            for i in range(2 * m):
                if j < i + 1:
                    j = i + 1
                while j < 2 * m and ext_pos[j] - ext_pos[i] < d:
                    j += 1
                right_conflict[i] = j - 1  # last index with perim dist < d

            # left_conflict[i] = smallest j < i such that ext_pos[i] - ext_pos[j] < d
            left_conflict = [0] * (2 * m)
            j = 0
            for i in range(2 * m - 1, -1, -1):
                if j > i - 1:
                    j = i - 1
                while j >= 0 and ext_pos[i] - ext_pos[j] < d:
                    j -= 1
                left_conflict[i] = j + 1  # first index with perim dist < d (from left)

            # Now greedy: try each starting point
            # After selecting point at index i (in unrolled), next point must be at
            # index > right_conflict[i] (to have perim dist >= d from i)
            # AND must pass manhattan check against all selected.

            # Since k <= 25, checking manhattan against all selected is O(k) per candidate.
            # The number of candidates we skip is bounded by the conflict window size.

            for s in range(m):
                selected = [s]
                # Next index must be > right_conflict[s]
                next_idx = right_conflict[s] + 1
                count = 1
                while count < k:
                    # Find next valid point from next_idx
                    found = False
                    while next_idx < s + m:
                        # Check perim distance to the last selected (already ensured by next_idx)
                        # But also need perim dist >= d from ALL selected
                        # Since selected points are increasing in perimeter, the closest
                        # selected to next_idx is the last one. So perim dist to last selected >= d
                        # is sufficient for perim dist to all selected >= d.

                        # Check manhattan against all selected
                        valid = True
                        cand_perim = ext_pos[next_idx]
                        for si in selected:
                            if manhattan(cand_perim % perimeter, ext_pos[si] % perimeter) < d:
                                valid = False
                                break
                        if valid:
                            selected.append(next_idx)
                            next_idx = right_conflict[next_idx] + 1
                            count += 1
                            found = True
                            break
                        next_idx += 1
                    if not found:
                        break
                if count >= k:
                    return True
            return False

        lo, hi = 1, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

