            mid = (lo + hi + 1) // 2
            if can_select(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        mapped = []
        for x, y in points:
            if y == 0:
                mapped.append((x, 0, x))
            elif x == side:
                mapped.append((side + y, 1, y))
            elif y == side:
                mapped.append((3 * side - x, 2, x))
            else:
                mapped.append((4 * side - y, 3, y))

        mapped.sort()
        S = 4 * side

        def get_manhattan(i, j):
            p1, e1, c1 = mapped[i]
            p2, e2, c2 = mapped[j]
            e_diff = abs(e1 - e2)
            if e_diff == 2:
                return side + abs(c1 - c2)
            else:
                dp = abs(p1 - p2)
                return min(dp, S - dp)

        def check(d):
            if d <= 0:
                return True
            corners = [0, side, 2 * side, 3 * side]

            for c in corners:
                rot_pos = []
                for i in range(n):
                    p = (mapped[i][0] - c) % S
                    rot_pos.append(p)

                order = sorted(range(n), key=lambda i: rot_pos[i])

                for s in range(n):
                    count = 1
                    last = order[s]
                    for t in range(1, n):
                        idx = order[(s + t) % n]
                        if get_manhattan(last, idx) >= d:
                            count += 1
                            last = idx
                            if count >= k:
                                return True

            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        per = 4 * side

        # Compute perimeter position for each point
        pos = []
        for x, y in points:
            if y == 0 and 0 <= x <= side:
                p = x
            elif x == side and 0 <= y <= side:
                p = side + y
            elif y == side and 0 <= x <= side:
                p = 2 * side + (side - x)
            else:  # x == 0
                p = 3 * side + (side - y)
            pos.append(p)

        pos.sort()

        # Duplicate for circular handling
        pos2 = pos + [p + per for p in pos]
        n2 = len(pos2)

        # Precompute next[i] = first index j > i such that pos2[j] - pos2[i] >= d
        # (recomputed for each d in binary search)

        def feasible(d):
            if d == 0:
                return True
            # Build next array using two pointers
            # next[i] = smallest j > i with pos2[j] >= pos2[i] + d
            nxt = [0] * n2
            j = 0
            for i in range(n2):
                if j < i + 1:
                    j = i + 1
                while j < n2 and pos2[j] < pos2[i] + d:
                    j += 1
                nxt[i] = j

            # Try each starting point (only first n to avoid duplicates)
            for start in range(n):
                cnt = 1
                cur = start
                while True:
                    nxt_pos = nxt[cur]
                    if nxt_pos >= start + n:
                        break
                    cnt += 1
                    if cnt >= k:
                        return True
                    # Check wrap-around: distance from last to first >= d
                    # pos2[nxt_pos] - pos2[start] <= per (guaranteed since nxt_pos < start + n)
                    # Wrap distance = per - (pos2[nxt_pos] - pos2[start])
                    if per - (pos2[nxt_pos] - pos2[start]) < d:
                        break
                    cur = nxt_pos
            return False

        lo, hi = 1, per
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

