                path.append(cur)
                cur = A[cur]
            elif state[cur] == 1:
                cycle_start = path.index(cur)
                cycle = path[cycle_start:]
                cycles.append(cycle)
                for node in cycle:
                    in_cycle[node] = True
                break
            else:
                break
        for node in path:
            state[node] = 2

    # Build children list
    children = [[] for _ in range(N)]
    for i in range(N):
        children[A[i]].append(i)

    # g[i][v] for v=0..M, processing non-cycle nodes bottom-up
    g = [None] * N

    non_cycle_children_count = [0] * N
    for i in range(N):
        if not in_cycle[i]:
            for child in children[i]:
                if not in_cycle[child]:
                    non_cycle_children_count[i] += 1

    queue = deque()
    for i in range(N):
        if not in_cycle[i] and non_cycle_children_count[i] == 0:
            queue.append(i)

    while queue:
        node = queue.popleft()
        # f(node, v) = product of g(child, v) for all non-cycle children
        f = [1] * (M + 1)
        for child in children[node]:
            if not in_cycle[child]:
                for v in range(1, M + 1):
                    f[v] = f[v] * g[child][v] % MOD
        # g(node, v) = prefix sum of f
        g[node] = [0] * (M + 1)
        for v in range(1, M + 1):
            g[node][v] = (g[node][v - 1] + f[v]) % MOD

        parent = A[node]
        if not in_cycle[parent]:
            non_cycle_children_count[parent] -= 1
            if non_cycle_children_count[parent] == 0:
                queue.append(parent)

