    ans = 1
    for cycle in cycles:
        # P(v) = product over cycle nodes of (product of g(non-cycle child, v))
        P = [1] * (M + 1)
        for cnode in cycle:
            for child in children[cnode]:
                if not in_cycle[child]:
                    for v in range(1, M + 1):
