    in_count = [0] * N
    for i in remaining:
        for c in children[i]:
            in_count[i] += 1
    # Process nodes bottom-up
    processed = set(i for i in range(N) if not on_cycle[i] and F[i] is not None)
    to_process = [i for i in range(N) if not on_cycle[i] and i not in processed]
    from collections import Counter
    child_count = [len(children[i]) for i in range(N)]
    pending = {}
    for i in to_process:
        c = child_count[i]
        pending[i] = c

