    for i in range(1, N + 1):
        if not in_cycle[i]:
            children[A[i]].append(i)

    order = []
    in_stack = [False] * (N + 1)
    for start in range(1, N + 1):
        if in_cycle[start] or in_stack[start]:
            continue
        stack = [start]
        in_stack[start] = True
        while stack:
            node = stack[-1]
            pushed = False
            for child in children[node]:
                if not in_stack[child]:
                    in_stack[child] = True
                    stack.append(child)
                    pushed = True
                    break
            if not pushed:
                order.append(node)
                stack.pop()

    g_poly = [None] * (N + 1)
    for node in order:
        if not children[node]:
            g_poly[node] = [0, 1]  # g = v
        else:
            f = [1]
            for child in children[node]:
                f = poly_mul(f, g_poly[child])
            g_poly[node] = poly_prefix_sum(f)

    answer = 1
    for cycle in cycles:
        h = [1]
        for node in cycle:
            for child in children[node]:
