def poly_mul(a, b):
    n, m = len(a), len(b)
    result = [0] * (n + m - 1)
    for i in range(n):
        if a[i] == 0:
            continue
        for j in range(m):
            if b[j] == 0:
                continue
            result[i + j] = (result[i + j] + a[i] * b[j]) % MOD
    return result


def poly_prefix_sum(f):
    d = len(f) - 1
    g = [0] * (d + 2)
    for k in range(d, -1, -1):
        g[k + 1] = (g[k + 1] + f[k] * pow(k + 1, MOD - 2, MOD)) % MOD
        for j in range(k + 1):
            co = comb(k + 1, k - j + 1) % MOD
            g[j] = (g[j] - g[k + 1] * co) % MOD
    for i in range(len(g)):
        g[i] %= MOD
    return g


def sum_poly_at_1_to_M(poly, M):
    total = 0
    for v in range(1, M + 1):
        val = 0
        pv = 1
        for i in range(len(poly)):
            val = (val + poly[i] * pv) % MOD
            pv = pv * v % MOD
        total = (total + val) % MOD
    return total


