import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx += 1
    p = int(input_data[idx]); idx += 1

    A = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append(int(input_data[idx])); idx += 1
        A.append(row)

    def mat_mult(X, Y, mod):
        n = len(X)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if X[i][k] == 0:
                    continue
                xik = X[i][k]
                for j in range(n):
                    if Y[k][j] == 0:
                        continue
                    result[i][j] = (result[i][j] + xik * Y[k][j]) % mod
        return result

    def mat_pow(M, exponent, mod):
        n = len(M)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1 % mod
        base = [row[:] for row in M]
        e = exponent
        while e > 0:
            if e & 1:
                result = mat_mult(result, base, mod)
            base = mat_mult(base, base, mod)
            e >>= 1
        return result

    if p == 2:
        B = [[1 if A[i][j] == 0 else A[i][j] for j in range(N)] for i in range(N)]
        result = mat_pow(B, 2, 2)
        for i in range(N):
            print(' '.join(map(str, result[i])))
        return

    # Build B0: non-zero entries of A stay, diagonal zeros get 1, off-diagonal zeros get 0
