        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if X[i][k] == 0:
                    continue
                xik = X[i][k]
                for j in range(n):
                    if Y[k][j] != 0:
                        result[i][j] = (result[i][j] + xik * Y[k][j]) % mod
        return result

    def mat_pow(M, exp, mod):
        n = len(M)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1 % mod
        base = [row[:] for row in M]
        while exp > 0:
            if exp & 1:
                result = mat_mul(result, base, mod)
            base = mat_mul(base, base, mod)
            exp >>= 1
        return result

    cp = mat_pow(C, p, p)

    # Build adjacency: for C-edges where A[i][j] != 0
    adj = [set() for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if C[i][j] != 0:
                adj[i].add(j)

    # component_id[i] = -1 if not in zero graph
    component_id = [-1] * N
    comp_size = []
    comp_count = 0
    for i in range(N):
        if C[i][i] == 0 and component_id[i] == -1:
            # BFS in zero graph (edges where C[u][v]==0 and u!=v)
            queue = deque([i])
            component_id[i] = comp_count
            size = 0
            while queue:
                u = queue.popleft()
                size += 1
                for v in range(N):
                    if u != v and C[u][v] == 0 and component_id[v] == -1:
                        component_id[v] = comp_count
                        queue.append(v)
            comp_size.append(size)
            comp_count += 1

    cycle_matrix = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            val = 0
            if i == j:
                if C[i][i] == 0:
                    cid = component_id[i]
                    sz = comp_size[cid]
                    for c in range(sz):
                        if c >= 1 and (c + 1) % sz != c:
                            val += pow(C[i][i], c + 1, p)
            # i != j: at most 2 values (c = (j-i)%sz and c = sz - (i-j)%sz)
            else:
                if C[i][j] == 0 and component_id[i] != -1:
                    cid = component_id[i]
                    sz = comp_size[cid]
                    if sz >= 2 and (i - j) % sz != (j - i) % sz:
                        c1 = (j - i) % sz
                        if c1 >= 1:
                            val += pow(C[i][j], c1, p)
                        c2 = sz - c1
                        if c2 >= 1:
                            val += pow(C[i][j], c2, p)
            cycle_matrix[i][j] = val % p

