import sys

def main():
    s = sys.stdin.buffer.readline().strip()
    n = len(s)

    # We need the longest palindromic suffix of S.
    # This is the same as the longest prefix of reverse(S)
    # that is also a suffix of S.
    rev = s[::-1]

    # Prefix function for rev.
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and rev[i] != rev[j]:
            j = pi[j - 1]
        if rev[i] == rev[j]:
            j += 1
        pi[i] = j

    # KMP scan of S against rev.
    q = 0
    for i, c in enumerate(s):
        while q > 0 and rev[q] != c:
            q = pi[q - 1]
        if rev[q] == c:
            q += 1
        if q == n and i != n - 1:
            q = pi[q - 1]

    longest_pal_suffix_len = q
    k = n - longest_pal_suffix_len

    # Append the reverse of the first k characters.
    if k > 0:
        ans = s + s[k - 1::-1]
    else:
        ans = s

    sys.stdout.buffer.write(ans + b"\n")

