def main() -> None:
    s = sys.stdin.buffer.readline().strip()
    n = len(s)
    if n == 0:
        return

    r = s[::-1]

    # Prefix function for reversed string r.
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        c = r[i]
        while j and c != r[j]:
            j = pi[j - 1]
        if c == r[j]:
            j += 1
        pi[i] = j

    # KMP automaton: find the longest prefix of r that is a suffix of s.
    j = 0
    for c in s:
        if j == n:
            j = pi[n - 1]
        while j and c != r[j]:
            j = pi[j - 1]
        if c == r[j]:
            j += 1

    # j is the length of the longest palindromic suffix of s.
    ans = s + s[:n - j][::-1]
    sys.stdout.buffer.write(ans + b"\n")

