class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        for d in range(-(n - 1), n):
            # Collect elements on this diagonal
            elems = []
            if d >= 0:
                for i in range(d, n):
                    elems.append(grid[i][i - d])
            else:
                for j in range(-d, n):
                    elems.append(grid[j + d][j])

            # Sort based on which triangle
            if d >= 0:
                elems.sort(reverse=True)  # non-increasing
            else:
                elems.sort()  # non-decreasing

            # Place elements back
            if d >= 0:
                for i in range(d, n):
                    grid[i][i - d] = elems[i - d]
            else:
                for j in range(-d, n):
                    grid[j + d][j] = elems[j + d]

        return grid

