import sys
from collections import deque

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    grid = []
    for _ in range(N):
        grid.append(input().strip())

    INF = float('inf')
    ans = [[INF] * N for _ in range(N)]

    # Precompute pred[v][c] = list of u where edge(u,v) has label c
    #              succ[v][c] = list of w where edge(v,w) has label c
    pred = [[[] for _ in range(26)] for _ in range(N)]
    succ = [[[] for _ in range(26)] for _ in range(N)]
    has_edge = [[False] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            c = grid[i][j]
            if c != '-':
                idx = ord(c) - ord('a')
                succ[i][idx].append(j)
                pred[j][idx].append(i)
                has_edge[i][j] = True

    # Even-length palindromic paths (center = vertex)
    # BFS from all (v, v) states
    dist_even = [[INF] * N for _ in range(N)]
    q = deque()
    for v in range(N):
        dist_even[v][v] = 0
        q.append((v, v))

    while q:
        u, v = q.popleft()
        d = dist_even[u][v]
        for c in range(26):
            if not pred[u][c] or not succ[v][c]:
                continue
            for u2 in pred[u][c]:
                for v2 in succ[v][c]:
                    if dist_even[u2][v2] == INF:
                        dist_even[u2][v2] = d + 1
                        q.append((u2, v2))

    for i in range(N):
        for j in range(N):
            if dist_even[i][j] < INF:
                ans[i][j] = 2 * dist_even[i][j]

    # Odd-length palindromic paths (center = edge)
    # BFS from all (u, v) where edge(u,v) exists
    dist_odd = [[INF] * N for _ in range(N)]
    q = deque()
    for u in range(N):
        for v in range(N):
            if has_edge[u][v]:
                dist_odd[u][v] = 0
                q.append((u, v))

    while q:
        u, v = q.popleft()
        d = dist_odd[u][v]
        for c in range(26):
            if not pred[u][c] or not succ[v][c]:
                continue
            for u2 in pred[u][c]:
                for v2 in succ[v][c]:
                    if dist_odd[u2][v2] == INF:
                        dist_odd[u2][v2] = d + 1
                        q.append((u2, v2))

    for i in range(N):
        for j in range(N):
            if dist_odd[i][j] < INF:
                total = 2 * dist_odd[i][j] + 1
                if total < ans[i][j]:
                    ans[i][j] = total

    # Output
    out = []
    for i in range(N):
        row = []
        for j in range(N):
            if ans[i][j] == INF:
                row.append('-1')
            else:
                row.append(str(ans[i][j]))
        out.append(' '.join(row))

    print('\n'.join(out))

solve()

