def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    C = []
    for i in range(N):
        C.append(input().strip())

    # pred[x*26+c] = list of u such that edge(u->x) has label c
    # succ[x*26+c] = list of v such that edge(x->v) has label c
    pred = [[] for _ in range(N * 26)]
    succ = [[] for _ in range(N * 26)]

    for i in range(N):
        for j in range(N):
            if C[i][j] != '-':
                c = ord(C[i][j]) - ord('a')
                succ[i * 26 + c].append(j)
                pred[j * 26 + c].append(i)

    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    queue = deque()

    # Initialize: distance 0 for (u,u), distance 1 for direct edges
    for u in range(N):
        dist[u][u] = 0
        queue.append((u, u))

    for u in range(N):
        for v in range(N):
            if C[u][v] != '-' and 1 < dist[u][v]:
                dist[u][v] = 1
                queue.append((u, v))

    # BFS: from state (up, vp) at distance d, reach (u, v) at d+2
    # if edge(u,up) and edge(vp,v) share the same label
    while queue:
