    N = int(input().strip())
    C = []
    for _ in range(N):
        C.append(input().strip())

    # Precompute incoming and outgoing edges by character
    # inc[c*N + v] = list of u where edge u->v has label c
    # out[c*N + v] = list of w where edge v->w has label c
    inc = [[] for _ in range(26 * N)]
    out = [[] for _ in range(26 * N)]

    for i in range(N):
        for j in range(N):
            if C[i][j] != '-':
                c = ord(C[i][j]) - ord('a')
                inc[c * N + j].append(i)
                out[c * N + i].append(j)

    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    queue = deque()

    # Base case: empty path (length 0)
    for i in range(N):
        dist[i][i] = 0
        queue.append((i, i))

    # Base case: single edge (length 1)
    for i in range(N):
        for j in range(N):
            if C[i][j] != '-' and dist[i][j] > 1:
                dist[i][j] = 1
                queue.append((i, j))

    # BFS expansion
    while queue:
        u, v = queue.popleft()
        d = dist[u][v]
        for c in range(26):
            for nu in inc[c * N + u]:
                for nv in out[c * N + v]:
                    if dist[nu][nv] > d + 2:
                        dist[nu][nv] = d + 2
                        queue.append((nu, nv))

    # Output
    result = []
    for i in range(N):
        row = []
        for j in range(N):
            if dist[i][j] == INF:
                row.append('-1')
            else:
                row.append(str(dist[i][j]))
        result.append(' '.join(row))
    print('\n'.join(result))

