    for i in range(N):
        ans[i][i] = 0

    # Odd lengths (2d+1): good states are (u,v) where edge(u->v) exists
    dist_odd = [[-1] * N for _ in range(N)]
    queue = deque()
    for u in range(N):
        for v, c in out_edges[u]:
