                length = 2 * dist_odd[i][j] + 1
                if ans[i][j] == -1 or length < ans[i][j]:
                    ans[i][j] = length

    # Even lengths (2d, d>=1): good states are (u,u)
    dist_even = [[-1] * N for _ in range(N)]
    queue = deque()
    for u in range(N):
        dist_even[u][u] = 0
        queue.append((u, u))

    while queue:
        a, b = queue.popleft()
        d = dist_even[a][b]
