def solve():
    input_data = sys.stdin.read().splitlines()
    N = int(input_data[0])
    C = []
    for i in range(1, N + 1):
        C.append(input_data[i].strip())

    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]

    in_by_char = [{c: [] for c in range(26)} for _ in range(N)]
    out_by_char = [{c: [] for c in range(26)} for _ in range(N)]

    for i in range(N):
        for j in range(N):
            if C[i][j] != '-':
                c = ord(C[i][j]) - ord('a')
                out_by_char[i][c].append(j)
                in_by_char[j][c].append(i)

    heap = []
    for i in range(N):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for j in range(N):
            if i != j and C[i][j] != '-':
                dist[i][j] = 1
                heapq.heappush(heap, (1, i, j))

    while heap:
        d, u, v = heapq.heappop(heap)
        if d != dist[u][v]:
            continue
        for c in range(26):
            ins = in_by_char[u][c]
            outs = out_by_char[v][c]
            if not ins or not outs:
                continue
            for i in ins:
                for j in outs:
                    nd = d + 2
                    if nd < dist[i][j]:
                        dist[i][j] = nd
                        heapq.heappush(heap, (nd, i, j))

    out_lines = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append('-1' if dist[i][j] == INF else str(dist[i][j]))
        out_lines.append(' '.join(row))
    print('\n'.join(out_lines))

