import sys

def solve():
    input = sys.stdin.readline
    N, K = map(int, input().split())
    A = list(map(int, input().split()))

    MOD = 998244353

    # Compute prefix sums S_0, S_1, ..., S_N
    S = [0] * (N + 1)
    for i in range(N):
        S[i + 1] = (S[i] + A[i]) % MOD

    # Precompute binomial coefficients C(K, t)
    binom = [[0] * (K + 1) for _ in range(K + 1)]
    for i in range(K + 1):
        binom[i][0] = 1
        for j in range(1, i + 1):
            binom[i][j] = binom[i-1][j-1] + binom[i-1][j]

    ans = 0

    # For each t, compute sum over r of S_r^t * (sum over j < r of S_j^(K-t))
    for t in range(K + 1):
        coeff = binom[K][t]
        if (K - t) % 2 == 1:
            coeff = -coeff
        coeff %= MOD

        # prefix_sum = sum of S_j^(K-t) for j = 0..r-1
        if K - t == 0:
            prefix_sum = 1  # 0^0 = 1
        else:
            prefix_sum = 0  # 0^(positive) = 0

        for r in range(1, N + 1):
            # Compute S_r^t
            if t == 0:
                sr_t = 1
            else:
                sr_t = pow(S[r], t, MOD)

            ans = (ans + coeff * sr_t % MOD * prefix_sum) % MOD

            # Add S_r^(K-t) to prefix_sum
            if K - t == 0:
                prefix_sum = (prefix_sum + 1) % MOD
            else:
                prefix_sum = (prefix_sum + pow(S[r], K - t, MOD)) % MOD

    ans %= MOD
    print(ans)

