def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1
    F = []
    for i in range(H):
        row = []
        for j in range(W):
            row.append(int(data[idx])); idx += 1
        F.append(row)

    Q = int(data[idx]); idx += 1
    queries = []
    for i in range(Q):
        a = int(data[idx]) - 1; idx += 1
        b = int(data[idx]) - 1; idx += 1
        y = int(data[idx]); idx += 1
        c = int(data[idx]) - 1; idx += 1
        d = int(data[idx]) - 1; idx += 1
        z = int(data[idx]); idx += 1
        queries.append((a, b, y, c, d, z))

    N = H * W
    max_F = max(max(row) for row in F)

    cells = []
    for i in range(H):
        for j in range(W):
            cells.append((F[i][j], i * W + j))
    cells.sort(reverse=True)

    pre_src = [q[0] * W + q[1] for q in queries]
    pre_dst = [q[3] * W + q[4] for q in queries]

    lo = [1] * Q
    hi = [max_F + 1] * Q

    parent = list(range(N))
    active = [False] * N

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    while True:
        all_done = True
        mids = defaultdict(list)
        for i in range(Q):
            if lo[i] == hi[i] - 1:
                continue
            all_done = False
            mid = (lo[i] + hi[i]) // 2
            mids[mid].append(i)

        if all_done:
            break

        for i in range(N):
            parent[i] = i
            active[i] = False

        cell_idx = 0
        sorted_mids = sorted(mids.keys(), reverse=True)

        for mid in sorted_mids:
            while cell_idx < N and cells[cell_idx][0] >= mid:
                _, ci = cells[cell_idx]
                active[ci] = True
                r, c = divmod(ci, W)
                if r > 0:
                    ni = ci - W
                    if active[ni]:
                        ri, rj = find(ci), find(ni)
                        if ri != rj:
                            parent[rj] = ri
                if r < H - 1:
                    ni = ci + W
                    if active[ni]:
                        ri, rj = find(ci), find(ni)
                        if ri != rj:
                            parent[rj] = ri
                if c > 0:
                    ni = ci - 1
                    if active[ni]:
                        ri, rj = find(ci), find(ni)
                        if ri != rj:
                            parent[rj] = ri
                if c < W - 1:
                    ni = ci + 1
                    if active[ni]:
                        ri, rj = find(ci), find(ni)
                        if ri != rj:
                            parent[rj] = ri
                cell_idx += 1

            for qi in mids[mid]:
                if find(pre_src[qi]) == find(pre_dst[qi]):
                    lo[qi] = mid
                else:
                    hi[qi] = mid

    out = []
    for i in range(Q):
        y = queries[i][2]
        z = queries[i][5]
        M = lo[i]
        ans = max(abs(y - z), y + z - 2 * M)
        out.append(str(ans))

    sys.stdout.write('\n'.join(out) + '\n')

