import sys
from collections import defaultdict, deque

def solve():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    F = []
    for i in range(H):
        F.append(list(map(int, input().split())))

    n = H * W
    edges = []
    for i in range(H):
        for j in range(W):
            u = i * W + j
            if i + 1 < H:
                v = (i+1) * W + j
                w = min(F[i][j], F[i+1][j])
                edges.append((w, u, v))
            if j + 1 < W:
                v = i * W + (j+1)
                w = min(F[i][j], F[i][j+1])
                edges.append((w, u, v))

    edges.sort(reverse=True)

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1
        return True

    tree = [[] for _ in range(n)]
    for w, u, v in edges:
        if union(u, v):
            tree[u].append((v, w))
            tree[v].append((u, w))

    LOG = max(1, n).bit_length()
    up = [[0] * n for _ in range(LOG)]
    mn = [[10**9] * n for _ in range(LOG)]
    depth = [0] * n
    visited = [False] * n

    for start in range(n):
        if not visited[start]:
            visited[start] = True
            depth[start] = 0
            up[0][start] = start
            mn[0][start] = 10**9
            q = deque([start])
            while q:
                u = q.popleft()
                for v, w in tree[u]:
                    if not visited[v]:
                        visited[v] = True
                        depth[v] = depth[u] + 1
                        up[0][v] = u
                        mn[0][v] = w
                        q.append(v)

    for k in range(1, LOG):
        upk = up[k]
        upk_1 = up[k-1]
        mnk = mn[k]
        mnk_1 = mn[k-1]
        for v in range(n):
            mid = upk_1[v]
            upk[v] = upk_1[mid]
            a = mnk_1[v]
            b = mnk_1[mid]
            mnk[v] = a if a < b else b

    def query_path_min(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        result = 10**9
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if diff & (1 << k):
                if mn[k][u] < result:
                    result = mn[k][u]
                u = up[k][u]
        if u == v:
            return result
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                if mn[k][u] < result:
                    result = mn[k][u]
                if mn[k][v] < result:
                    result = mn[k][v]
                u = up[k][u]
                v = up[k][v]
        if mn[0][u] < result:
            result = mn[0][u]
        if mn[0][v] < result:
            result = mn[0][v]
        return result

    Q = int(input())
    out = []
    for _ in range(Q):
        a, b, y, c, d, z = map(int, input().split())
        a -= 1; b -= 1; c -= 1; d -= 1
        u = a * W + b
        v = c * W + d
        if u == v:
            out.append(abs(y - z))
        else:
            x_star = query_path_min(u, v)
            diff = y - z
            if diff < 0:
                diff = -diff
            val = y + z - 2 * x_star
            if val < diff:
                val = diff
            out.append(val)

    sys.stdout.write('\n'.join(map(str, out)) + '\n')

solve()

