from array import array

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    K = int(next(it))

    # Store the values compactly and count frequencies.
    A = array('I')
    A.fromlist([int(x) for x in it])

    # For K = 1, taking only A_i gives gcd A_i, which is trivially optimal.
    if K == 1:
        out = sys.stdout.write
        # Write in chunks to avoid creating a huge list of strings.
        CH = 10000
        for start in range(0, N, CH):
            end = min(start + CH, N)
            out('\n'.join(str(A[j]) for j in range(start, end)))
            if end < N:
                out('\n')
        if N:
            out('\n')
        return

    M = max(A) if N else 0
    if M == 0:
        return

    freq = [0] * (M + 1)
    for v in A:
        freq[v] += 1

    # ans[x] will become the maximum d such that:
    #   d divides x and at least K elements of A are divisible by d.
    ans = [0] * (M + 1)

    # Process d from large to small. Once ans[m] is set, it is final.
    M1 = M + 1
    freq_local = freq
    ans_local = ans
    K_local = K

    for d in range(M, 0, -1):
        s = 0
        # Count how many array elements are multiples of d.
        # Stop early once we know d is "good".
        for m in range(d, M1, d):
            c = freq_local[m]
            if c:
                s += c
                if s >= K_local:
                    break

        if s >= K_local:
            # Assign this d to all multiples that have not been assigned yet.
            # Since d decreases, the first assignment is the maximum valid divisor.
            for m in range(d, M1, d):
                if ans_local[m] == 0:
                    ans_local[m] = d

    # Output answers in input order, writing in manageable chunks.
    out = sys.stdout.write
    CH = 10000
    for start in range(0, N, CH):
        end = min(start + CH, N)
        out('\n'.join(str(ans_local[A[j]]) for j in range(start, end)))
        if end < N:
            out('\n')
    if N:
        out('\n')

if __name__ == "__main__":
    main()

