class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'

        a = []
        b = []
        i = 0
        n = len(t)
        while i < n:
            if t[i] == '1':
                j = i
                while j < n and t[j] == '1':
                    j += 1
                a.append(j - i)
                i = j
            else:
                j = i
                while j < n and t[j] == '0':
                    j += 1
                b.append(j - i)
                i = j

        original_ones = s.count('1')
        k = len(b)

        if k < 2:
            return original_ones

        max_gain = 0
        sum_b = sum(b)
        b_sorted = sorted(b, reverse=True)
        max1 = b_sorted[0]
        max2 = b_sorted[1] if len(b_sorted) > 1 else 0
        count_max1 = b.count(max1)

        for i in range(1, k):
            gain_a = b[i - 1] + b[i]

            other_sum = sum_b - b[i - 1] - b[i]
            if other_sum > 0:
                if b[i-1] == max1 and b[i] == max1:
                    best_other = max1 if count_max1 > 2 else max2
                elif b[i-1] == max1 or b[i] == max1:
                    best_other = max1 if count_max1 > 1 else max2
                else:
                    best_other = max1
                gain_b = best_other - a[i]
            else:
                gain_b = 0

            max_gain = max(max_gain, gain_a, gain_b)

        return original_ones + max_gain

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        from collections import Counter
        count = Counter(digits)
        result = 0

        for last in range(0, 10, 2):  # even digits: 0, 2, 4, 6, 8
            if count[last] < 1:
                continue
            for first in range(1, 10):  # 1-9, no leading zero
                # Check if we can use 'first' and 'last' together
                if first == last:
                    if count[last] < 2:
                        continue
                else:
                    if count[first] < 1 or count[last] < 1:
                        continue
                for mid in range(0, 10):
                    # After using 'first' and 'last', check if 'mid' is still available
                    remaining = count[mid]
                    if mid == first:
                        remaining -= 1
                    if mid == last:
                        remaining -= 1
                    if remaining >= 1:
                        result += 1

        return result

