from typing import List

class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        freq = Counter(digits)
        count = 0
        for num in range(100, 1000, 2):
            d1, d2, d3 = num // 100, (num // 10) % 10, num % 10
            needed = Counter([d1, d2, d3])
            if all(needed[d] <= freq[d] for d in needed):
                count += 1
        return count

