class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        lower = 0
        upper = float('inf')

        for i in range(n):
            d = original[i] - original[0]
            lower = max(lower, bounds[i][0] - d)
            upper = min(upper, bounds[i][1] - d)

        return max(0, upper - lower + 1)

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        n = len(original)
        base = original[0]

        low = float('-inf')
        high = float('inf')

        for i in range(n):
            diff = original[i] - base
            u, v = bounds[i]
            low = max(low, u - diff)
            high = min(high, v - diff)

        return max(0, high - low + 1)

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        max_lower = float('-inf')
        min_upper = float('inf')

        for i in range(len(original)):
            lower = bounds[i][0] - original[i]
            upper = bounds[i][1] - original[i]
            max_lower = max(max_lower, lower)
            min_upper = min(min_upper, upper)

        return max(0, min_upper - max_lower + 1)

