def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    # Binary search the maximum number K of kagamimochi.
    # For a candidate K, it is sufficient and necessary to check:
    #   2 * A[i] <= A[N-K+i]  for all i = 0 .. K-1
    lo, hi = 0, N // 2 + 1

    def can(k: int) -> bool:
        start_bottom = N - k
        for i in range(k):
            if 2 * A[i] > A[start_bottom + i]:
                return False
        return True

    while hi - lo > 1:
        mid = (lo + hi) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid

    print(lo)

