def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]

    first = [n] * (n + 1)
    last = [-1] * (n + 1)

    for i in range(n):
        x = data[i + 1]
        if first[x] == n:
            first[x] = i
        last[x] = i

    diff = [0] * n

    for x in range(1, n + 1):
        f = first[x]
        if f != n:
            l = last[x]

            # This value is in the left subarray for splits i where f <= i <= n - 2
            if f <= n - 2:
                diff[f] += 1
                diff[n - 1] -= 1

            # This value is in the right subarray for splits i where 0 <= i <= l - 1
            if l > 0:
                diff[0] += 1
                diff[l] -= 1

    ans = 0
    cur = 0

    for i in range(n - 1):
        cur += diff[i]
        if cur > ans:
            ans = cur

    print(ans)

