import sys
input = sys.stdin.buffer.read().split()
idx = 0
T = int(input[idx]); idx += 1
out = []
for _ in range(T):
    N = int(input[idx]); idx += 1
    A = input[idx].decode(); idx += 1
    B = input[idx].decode(); idx += 1

    a_pos = [i+1 for i in range(N) if A[i] == '1']
    b_pos = [i+1 for i in range(N) if B[i] == '1']
    k = len(a_pos)
    m = len(b_pos)

    if k < m:
        out.append("-1")
        continue

    spread_a = a_pos[-1] - a_pos[0]
    spread_b = b_pos[-1] - b_pos[0]
    if spread_a < spread_b:
        out.append("-1")
        continue

    def can(r):
        if r == 0:
            for b in b_pos:
                if b not in set(a_pos):
                    return False
            return True
        # For x operations moving piece left, (r-x) moving right:
        # reachable range for piece at p: [p-x, p+(r-x)]
        # We sweep x from 0 to r, tracking union of reachable intervals.
        # x* = clamp(b1 - a1, 0, r) is the optimal x for covering b1.
        x_star = b_pos[0] - a_pos[0]
        if x_star < 0:
            x_star = 0
        if x_star > r:
            x_star = r
        # Count coverage of each target position
        diff = [0] * (N + 2)
        for p in a_pos:
            lo = p - x_star
            hi = p + (r - x_star)
            if lo < 1:
                lo = 1
            if hi > N:
                hi = N
            if lo <= hi:
                diff[lo] += 1
                diff[hi + 1] -= 1
        running = 0
        for b in b_pos:
            running += diff[b]
            if running < 1:
                return False
        return True

    lo, hi = 0, 2 * N + 2
    while lo < hi:
        mid = (lo + hi) // 2
        if can(mid):
            hi = mid
        else:
            lo = mid + 1

    if can(lo):
        out.append(str(lo))
    else:
        out.append("-1")

print('\n'.join(out))

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)

        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        count = 0
        # Stack of (left_bound, right_bound) for open regions
        stack = []
        cur_begin = 0
        cur_reach = last[s[0]]
        cur_bound = first[s[0]]

        for i in range(1, n):
            c = s[i]
            new_reach = max(cur_reach, last[c])
            new_bound = min(cur_bound, first[c])

            if new_reach == cur_reach and i >= cur_reach:
                # Current segment is a valid closed interval
                region_left = cur_begin
                region_right = i
                # Pop stack entries that are contained within this region
                while stack and stack[-1][1] <= region_right:
                    stack.pop()
                # If region is "free" (not constrained by outer region), it's atomic
                lower_bound = stack[-1][1] if stack else -1
                if region_left > lower_bound and not (region_left == 0 and region_right == n - 1):
                    count += 1
                # Start new segment
                cur_begin = i + 1
                if i + 1 < n:
                    nc = s[i + 1]
                    cur_reach = last[nc]
                    cur_bound = first[nc]
            else:
                cur_reach = new_reach
                cur_bound = new_bound

        return count >= k

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        first = {}
        last = {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i

        count = 0
        l = 0
        while l < n:
            if first[s[l]] < l:
                l += 1
                continue
            r = l
            valid = True
            i = l
            while i <= r:
                if first[s[i]] < l:
                    valid = False
                    break
                r = max(r, last[s[i]])
                i += 1
            if valid and r < n - 1:
                count += 1
                if count >= k:
                    return True
                l = r + 1
            else:
                l += 1

        return count >= k

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True

        # Compute last occurrence of each character
        last = {}
        for i, c in enumerate(s):
            last[c] = i

        count = 0
        partition_start = 0
        partition_end = 0

        for i in range(n):
            partition_end = max(partition_end, last[s[i]])
            if i == partition_end:
                # Found a closed partition [partition_start, partition_end]
                if not (partition_start == 0 and partition_end == n - 1):
                    count += 1
                partition_start = i + 1
                partition_end = 0

        return count >= k

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        if k > 26:
            return False

        first_occ = [n] * 26
        last_occ = [-1] * 26
        for i, ch in enumerate(s):
            c = ord(ch) - ord('a')
            first_occ[c] = min(first_occ[c], i)
            last_occ[c] = max(last_occ[c], i)

        count = 0
        i = 0
        while i < n:
            # Compute the minimal closing interval starting at i
            c = ord(s[i]) - ord('a')
            end = last_occ[c]
            j = i + 1
            while j <= end:
                c2 = ord(s[j]) - ord('a')
                if last_occ[c2] > end:
                    end = last_occ[c2]
                j += 1

            # Check if interval [i, end] is a valid special substring
            # (every character in it must have first_occ >= i)
            valid = True
            for j in range(i, end + 1):
                c2 = ord(s[j]) - ord('a')
                if first_occ[c2] < i:
                    valid = False
                    break

            if valid and (i > 0 or end < n - 1):
                count += 1
                if count >= k:
                    return True
                i = end + 1
            else:
