        return count >= k

class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)

        first = [n] * 26
        last = [-1] * 26
        for i, ch in enumerate(s):
            idx = ord(ch) - ord('a')
            first[idx] = min(first[idx], i)
            last[idx] = max(last[idx], i)

        # A position is blocked if its character spans the entire string
        blocked = [False] * n
        for i in range(n):
            idx = ord(s[i]) - ord('a')
            if first[idx] == 0 and last[idx] == n - 1:
                blocked[i] = True

        count = 0
        i = 0
        while i < n:
            if blocked[i]:
                i += 1
                continue
            # Find the unblocked segment [seg_start, seg_end]
            seg_start = i
            while i < n and not blocked[i]:
                i += 1
            seg_end = i - 1

            # Greedily count finest closed intervals within the segment
            current_end = -1
            for j in range(seg_start, seg_end + 1):
                idx = ord(s[j]) - ord('a')
                current_end = max(current_end, last[idx])
                if current_end > seg_end:
                    current_end = seg_end
                if j == current_end:
                    count += 1
                    current_end = -1

        return count >= k

