class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)

        first = [n] * 26
        last = [-1] * 26
        for i, ch in enumerate(s):
            c = ord(ch) - ord('a')
            first[c] = min(first[c], i)
            last[c] = max(last[c], i)

        present = [c for c in range(26) if last[c] >= 0]
        m = len(present)

        if m == 1:
            # Single block: only subsets of size >= 2 can form valid special substrings
            # (single char would equal the entire string)
            min_size = 2
        else:
            min_size = 1

        # Prefix/suffix character masks
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] | (1 << (ord(s[i]) - ord('a')))
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] | (1 << (ord(s[i]) - ord('a')))

        def range_mask(l, r):
            return (prefix[r + 1] ^ prefix[l]) | (suffix[l] & suffix[r + 1])

        all_mask = (1 << m) - 1
        size = 1 << m

        # Check which subsets form valid special substrings
        valid = [False] * size
        for mask in range(1, size):
            # Count bits
            bits = [present[i] for i in range(m) if mask & (1 << i)]
            if len(bits) < min_size:
                continue
            lo = min(first[c] for c in bits)
            hi = max(last[c] for c in bits)
            if range_mask(lo, hi) == mask:
                valid[mask] = True

        # DP over subsets: dp[mask] = max special substrings from characters in mask
        dp = [0] * size
        for mask in range(1, size):
            if valid[mask]:
                dp[mask] = 1
            sub = (mask - 1) & mask
            while sub > 0:
                if valid[sub]:
                    dp[mask] = max(dp[mask], 1 + dp[mask ^ sub])
                sub = (sub - 1) & mask

        return dp[all_mask] >= k

