def solve():
    input_data = sys.stdin.buffer.read().split()
    n = int(input_data[0])
    A = [int(input_data[i + 1]) for i in range(n)]

    if n == 2:
        print(abs(A[0] - A[1]))
        return

    NEG = float('-inf')

    # dpE[i] = max score for prefix A[0..i-1] (length i, even)
    # dpO[i] = max score for prefix A[0..i-1] (length i, odd)

    dpE = [NEG] * (n + 1)
    dpO = [NEG] * (n + 1)
    dpE[0] = 0
    dpO[1] = 0  # single element, no score

    for pos in range(1, n + 1):
        if pos % 2 == 0:
            # Compute dpE[pos]
            # Option 1: size-2 block at the end → dpE[pos-2] + |A[pos-2]-A[pos-1]|
            if dpE[pos - 2] != NEG:
                dpE[pos] = dpE[pos - 2] + abs(A[pos - 2] - A[pos - 1])
            # Option 2: size-4 block at the end → dpE[pos-4] + block4(A[pos-4..pos-1])
            if pos >= 4 and dpE[pos - 4] != NEG:
                a, b, c, d = A[pos-4], A[pos-3], A[pos-2], A[pos-1]
                block4 = (max(a,b,c,d) - min(a,b,c,d)) + min(abs(a-c), abs(b-d))
                val = dpE[pos - 4] + block4
                if val > dpE[pos]:
                    dpE[pos] = val
        else:
            # Compute dpO[pos]
            # Option 1: single at end → dpE[pos-1] + 0
            if dpE[pos - 1] != NEG:
                dpO[pos] = dpE[pos - 1]
            # Option 2: size-2 block at the end → dpO[pos-2] + |A[pos-2]-A[pos-1]|
            if pos >= 3 and dpO[pos - 2] != NEG:
                val = dpO[pos - 2] + abs(A[pos - 2] - A[pos - 1])
                if val > dpO[pos]:
                    dpO[pos] = val
            # Option 3: size-4 block at the end → dpO[pos-4] + block4(A[pos-4..pos-1])
            if pos >= 5 and dpO[pos - 4] != NEG:
                a, b, c, d = A[pos-4], A[pos-3], A[pos-2], A[pos-1]
                block4 = (max(a,b,c,d) - min(a,b,c,d)) + min(abs(a-c), abs(b-d))
                val = dpO[pos - 4] + block4
                if val > dpO[pos]:
                    dpO[pos] = val

    if n % 2 == 0:
        print(dpE[n])
    else:
        print(dpO[n])

