class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        n = len(pizzas)
        k = n // 4
        odd_count = (k + 1) // 2
        even_count = k // 2

        total = 0

        for i in range(odd_count):
            total += pizzas[i]

        for i in range(even_count):
            total += pizzas[odd_count + 2 * i + 1]

        return total

class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        k = len(pizzas) // 4
        result = 0
        for i in range(k):
            idx = (3 * i + i % 2) // 2
            result += pizzas[idx]
        return result

class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        n = len(pizzas)
        left, right = 0, n - 1
        result = 0
        for day in range(n // 4):
            if day % 2 == 0:  # odd-numbered day (1-indexed), gain Z (largest)
                result += pizzas[left]
                left += 1
                right -= 3
            else:  # even-numbered day, gain Y (second largest)
                result += pizzas[left + 1]
                left += 2
                right -= 2
        return result

