class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[(parity, sum)] = set of achievable products (non-empty subsequences)
        # parity 0: even count so far, next element is added
        # parity 1: odd count so far, next element is subtracted
        dp = {}

        for num in nums:
            updates = {}

            # Option: start a new subsequence with this num
            # 1 element picked (odd), so parity becomes 1, sum = num
            if num <= limit:
                key = (1, num)
                if key not in updates:
                    updates[key] = set()
                updates[key].add(num)

            # Option: extend existing subsequences
            for (p, s), prods in dp.items():
                if p == 0:
                    new_s = s + num   # even count -> next at even index -> add
                else:
                    new_s = s - num   # odd count -> next at odd index -> subtract
                new_p = 1 - p
                key = (new_p, new_s)
                if key not in updates:
                    updates[key] = set()
                for prod in prods:
                    new_prod = prod * num
                    if new_prod <= limit:
                        updates[key].add(new_prod)

            # Apply updates (0/1 knapsack: use old dp for transitions)
            for key, prods in updates.items():
                if key in dp:
                    dp[key].update(prods)
                else:
                    dp[key] = prods

        # Find the maximum product with sum == k
        ans = -1
        for p in (0, 1):
            if (p, k) in dp:
                for prod in dp[(p, k)]:
                    if prod > ans:
                        ans = prod

        return ans

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[parity][s_offset] = max product achievable (or -1 if not reachable)
        # parity 0 = even count chosen (next element gets +), parity 1 = odd count (next gets -)
        OFFSET = 1800
        SIZE = 3601

        NEG = -1  # unreachable
        dp = [[NEG] * SIZE for _ in range(2)]
        dp[0][OFFSET] = 1  # empty subsequence: parity 0, sum 0, product 1

        for x in nums:
            new_dp = [row[:] for row in dp]
            for parity in range(2):
                for si in range(SIZE):
                    p = dp[parity][si]
                    if p < 0:
                        continue
                    new_p = p * x
                    if new_p > limit:
                        continue
                    if parity == 0:
                        ns = si + x
                    else:
                        ns = si - x
                    if 0 <= ns < SIZE:
                        if new_p > new_dp[1 - parity][ns]:
                            new_dp[1 - parity][ns] = new_p
            # Start a new subsequence with just this element
            if x <= limit:
                if x > new_dp[1][OFFSET + x]:
                    new_dp[1][OFFSET + x] = x
            dp = new_dp

        # Find max product where alternating sum == k
        if -OFFSET <= k <= OFFSET:
            ans = max(dp[0][OFFSET + k], dp[1][OFFSET + k])
            return ans if ans > 0 else -1
        return -1

