    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[0]: set of (sum, product) for even-length subsequences
        # dp[1]: set of (sum, product) for odd-length subsequences
        dp = [set(), set()]

        for num in nums:
            old_dp0 = set(dp[0])
            old_dp1 = set(dp[1])

            # Start a new subsequence with just this num (length 1, odd)
            if num <= limit:
