            # Extend even-length subsequences by adding num -> becomes odd-length
            for (s, p) in old_dp0:
                new_p = p * num
                if new_p <= limit:
                    dp[1].add((s + num, new_p))

            # Extend odd-length subsequences by subtracting num -> becomes even-length
            for (s, p) in old_dp1:
                new_p = p * num
                if new_p <= limit:
                    dp[0].add((s - num, new_p))

        ans = -1
        for state_set in (dp[0], dp[1]):
            for (s, p) in state_set:
                if s == k and p > ans:
                    ans = p
        return ans

