    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        MAX_SUM = sum(nums)
        MIN_SUM = -MAX_SUM
        offset = -MIN_SUM
        size = MAX_SUM - MIN_SUM + 1

        if k < MIN_SUM or k > MAX_SUM:
            return -1

        # dp[p][s] = max product for non-empty subsequence with alternating sum s,
        # p=0: even length so far, p=1: odd length so far
        dp = [[-1] * size for _ in range(2)]

        for num in nums:
            new_dp = [row[:] for row in dp]

