            if num <= limit:
                s = num + offset
                if 0 <= s < size and num > new_dp[1][s]:
                    new_dp[1][s] = num

            # Extend existing subsequences (using old dp to avoid reusing same element)
            for p in range(2):
                for s in range(size):
                    if dp[p][s] == -1:
                        continue
                    prod = dp[p][s]
                    if p == 0:
                        new_s_idx = s + num
                    else:
                        new_s_idx = s - num
