                        new_prod = prod * num
                        if new_prod > limit:
                            continue
                        new_p = 1 - p
                        if new_prod > new_dp[new_p][new_s_idx]:
                            new_dp[new_p][new_s_idx] = new_prod

            dp = new_dp

        result = -1
        target = k + offset
        if 0 <= target < size:
            for p in range(2):
                if dp[p][target] > result:
                    result = dp[p][target]

        return result

