class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        from collections import defaultdict

        a_for_b = defaultdict(list)
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            a_for_b[b].append(a)

        max_a_at = [0] * (n + 1)
        for b in range(1, n + 1):
            if a_for_b[b]:
                max_a_at[b] = max(a_for_b[b])

        prefix_max = [0] * (n + 1)
        for j in range(1, n + 1):
            prefix_max[j] = max(prefix_max[j - 1], max_a_at[j])

        base = sum(j - prefix_max[j] for j in range(1, n + 1))
        best = base

        seen = set()
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if (a, b) in seen:
                continue
            seen.add((a, b))

            lst = a_for_b[b]
            if lst[0] != a:
                continue

            new_max_a = max(lst[1:]) if len(lst) > 1 else 0
            P = prefix_max[b - 1]

            total_improvement = 0
            R = 0
            j = b
            while j <= n:
                old_val = prefix_max[j]
                if old_val < a:
                    break
                if j > b:
                    if max_a_at[j] > R:
                        R = max_a_at[j]
                new_val = P
                if new_max_a > new_val:
                    new_val = new_max_a
                if R > new_val:
                    new_val = R
                total_improvement += old_val - new_val
                j += 1

            candidate = base + total_improvement
            if candidate > best:
                best = candidate

        return best

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        from collections import defaultdict
        import bisect

        # min_b[a] = minimum b among pairs (a, b) with a < b
        min_b = [float('inf')] * (n + 2)
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if b < min_b[a]:
                min_b[a] = b

        has_pair = [False] * (n + 2)
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            has_pair[a] = True

        # Compute best[i] and second_best[i] = two smallest min_b values among positions >= i
        best = [float('inf')] * (n + 2)
        second_best = [float('inf')] * (n + 2)
        for i in range(n, 0, -1):
            vb = min_b[i]
            pb, ps = best[i + 1], second_best[i + 1]
            if vb <= pb:
                best[i] = vb
                second_best[i] = pb
            else:
                best[i] = pb
                second_best[i] = min(vb, ps)

        # Total valid subarrays = sum(best[i] - i)
        total = 0
        for i in range(1, n + 1):
            total += best[i] - i

        # Prefix sums of second_best for efficient range queries
        prefix_sb = [0] * (n + 2)
        for i in range(1, n + 2):
            prefix_sb[i] = prefix_sb[i - 1] + second_best[i]

        ans = total  # at least we can remove any pair

        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if b != min_b[a]:
                continue

            # Find L: smallest i in [1, a] where best[i] == b
            # best is non-decreasing, so valid range is [L, a]
            lo, hi = 1, a
            while lo < hi:
                mid = (lo + hi) // 2
                if best[mid] == b:
                    hi = mid
                else:
                    lo = mid + 1
            L = lo

            # Gain = sum_{i=L}^{a} (second_best[i] - b)
            gain = (prefix_sb[a] - prefix_sb[L - 1]) - (a - L + 1) * b
            ans = max(ans, total + gain)

        return ans

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        min_b = [float('inf')] * (n + 2)
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if b < min_b[a]:
                min_b[a] = b

        right_limit = [float('inf')] * (n + 2)
        active = []
        for i in range(n, 0, -1):
            if min_b[i] < right_limit[i + 1]:
                right_limit[i] = min_b[i]
                if min_b[i] != float('inf'):
                    active.append(i)
            else:
                right_limit[i] = right_limit[i + 1]

        total = 0
        for i in range(1, n + 1):
            total += right_limit[i] - i

        if not active:
            return total

        # prefix[i] = sum of right_limit[1..i]
        prefix = [0] * (n + 2)
        for i in range(1, n + 2):
            prefix[i] = prefix[i - 1] + right_limit[i]

        m = len(active)
        # active[0] > active[1] > ... (decreasing indices)
        # right_limit[active[0]] < right_limit[active[1]] < ... (strictly increasing)

        # left_bound[j]: largest active index to the left of active[j] with strictly smaller right_limit
        # = "previous smaller element" in the sequence right_limit[active[0]], right_limit[active[1]], ...
        left_bound = [0] * m
        stk = []
        for j in range(m):
            while stk and right_limit[active[stk[-1]]] >= right_limit[active[j]]:
                stk.pop()
            left_bound[j] = active[stk[-1]] if stk else 0
            stk.append(j)

        best_gain = 0
        for j in range(m):
            a = active[j]
            val = right_limit[a]
            lb = left_bound[j]
            rb = active[j - 1] if j > 0 else n + 1
            left_sum = prefix[a - 1] - prefix[lb]
            right_sum = prefix[rb - 1] - prefix[a]
            gain = (left_sum + right_sum) - val * (rb - lb - 1)
            if gain > best_gain:
                best_gain = gain

        return total + best_gain

