    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        INF = float('inf')
        b_lists = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            b_lists[a].append(b)
        for a in range(1, n + 1):
            b_lists[a].sort()

        min_b = [INF] * (n + 2)
        for a in range(1, n + 1):
            if b_lists[a]:
                min_b[a] = b_lists[a][0]

        g = [INF] * (n + 2)
        for i in range(n, 0, -1):
            g[i] = min(min_b[i], g[i + 1])

        base = sum(min(n+1, g[i]) - i for i in range(1, n+1) if g[i] > i)

        best_gain = 0
        seen = set()
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if (a, b) in seen:
                continue
            seen.add((a, b))
            lst = b_lists[a]
            if lst[0] != b:
                continue
            idx = 0
            while idx < len(lst) and lst[idx] == b:
                idx += 1
            new_min_b_a = lst[idx] if idx < len(lst) else INF
            if new_min_b_a == min_b[a]:
                continue

            gain = 0
            oc = min(n+1, min_b[a]) - a if min(n+1, min_b[a]) > a else 0
            nc = min(n+1, new_min_b_a) - a if min(n+1, new_min_b_a) > a else 0
            gain += nc - oc

            new_g_ip1 = new_min_b_a
            for i in range(a - 1, 0, -1):
                if min_b[i] < new_min_b_a:
                    break
                new_gi = min(min_b[i], new_g_ip1)
                oc = min(n+1, g[i]) - i if min(n+1, g[i]) > i else 0
                nc = min(n+1, new_gi) - i if min(n+1, new_gi) > i else 0
                gain += nc - oc
                new_g_ip1 = new_gi

            best_gain = max(best_gain, gain)

        return base + best_gain

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        total = n * (n + 1) // 2

        h = [float('inf')] * (n + 2)
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if b < h[a]:
                h[a] = b

        f = [0] * (n + 2)
        f[n + 1] = n + 1
        for i in range(n, 0, -1):
            f[i] = min(h[i], f[i + 1])

        base = 0
        for i in range(1, n + 1):
            base += max(0, f[i] - i)

        critical = []
        for i in range(1, n + 1):
            if f[i] != f[i + 1]:
                critical.append(i)

        if not critical:
            return total

        best_gain = 0
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if f[a] != b or b > n:
                continue

            lo, hi = 0, len(critical) - 1
            seg_idx = 0
            while lo <= hi:
                mid = (lo + hi) // 2
                if critical[mid] <= a:
                    seg_idx = mid
                    lo = mid + 1
                else:
                    hi = mid - 1

            seg_start = critical[seg_idx]
            seg_end = critical[seg_idx + 1] - 1 if seg_idx + 1 < len(critical) else n

            next_level = f[seg_end + 1] if seg_end + 1 <= n else n + 1

            effective_end = min(seg_end, a)
            if effective_end < seg_start:
                continue

            gain = (next_level - b) * (effective_end - seg_start + 1)
            if gain > best_gain:
                best_gain = gain

        return base + best_gain

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        INF = n + 1
        pairs_at = [[] for _ in range(n + 2)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            pairs_at[a].append(b)

        minB = [INF] * (n + 3)
        for p in range(1, n + 1):
            if pairs_at[p]:
                minB[p] = min(pairs_at[p])

        limit = [INF] * (n + 3)
        for i in range(n, 0, -1):
            limit[i] = min(minB[i], limit[i + 1])

        base = 0
        for i in range(1, n + 1):
            base += min(limit[i], n + 1) - i

        best_gain = 0
        seen = set()

        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            if (a, b) in seen:
                continue
            seen.add((a, b))

            if b != minB[a]:
                continue

            # Count occurrences of b in pairs_at[a]
            count_b = sum(1 for x in pairs_at[a] if x == b)
            if count_b > 1:
                continue

            # Find new minB[a]
            new_minB_a = INF
            for x in pairs_at[a]:
                if x != b:
                    new_minB_a = min(new_minB_a, x)

            # Find range [s, a] where limit[i] == b
            s = a
            while s >= 1 and limit[s] == b:
                s -= 1
            s += 1

            new_val = min(new_minB_a, limit[a + 1])
            old_capped = min(b, n + 1)
            new_capped = min(new_val, n + 1)

            if new_capped > old_capped:
                gain = (new_capped - old_capped) * (a - s + 1)
                best_gain = max(best_gain, gain)

        return base + best_gain

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 1:
            return n * (n + 1) // 2

        pairs = []
        for a, b in conflictingPairs:
            lo, hi = (a, b) if a < b else (b, a)
            pairs.append((lo, hi))

        from collections import defaultdict
        by_hi = defaultdict(list)
        for idx, (lo, hi) in enumerate(pairs):
            by_hi[hi].append((lo + 1, idx))

        top1_val = 0
        top1_idx = -1
        top2_val = 0

        t1_val_arr = [0] * (n + 1)
        pair_savings = [0] * m

        for j in range(1, n + 1):
            for val, idx in by_hi.get(j, []):
                if val > top1_val:
                    top2_val = top1_val
                    top1_val, top1_idx = val, idx
                elif val > top2_val:
                    top2_val = val
            t1_val_arr[j] = top1_val
            if top1_idx != -1 and top1_val > max(1, top2_val):
                pair_savings[top1_idx] += top1_val - max(1, top2_val)

        base = 0
        for j in range(1, n + 1):
            base += j - max(1, t1_val_arr[j]) + 1

        best_answer = base
        for k in range(m):
            best_answer = max(best_answer, base + pair_savings[k])

        return best_answer

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[None] * n for _ in range(n)]

        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                dp[i][j] = [0] * (k + 1)
                diff = abs(ord(s[i]) - ord(s[j]))
                cost = min(diff, 26 - diff)
                for t in range(k + 1):
                    best = max(dp[i + 1][j][t], dp[i][j - 1][t])
                    if cost <= t:
                        if i + 1 <= j - 1:
                            best = max(best, 2 + dp[i + 1][j - 1][t - cost])
                        else:
                            best = max(best, 2)
                    dp[i][j][t] = best

        return dp[0][n - 1][k]

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, j, rem):
            if i > j:
                return 0
            if i == j:
                return 1
            # Option 1: don't pair s[i] with s[j]
            res = max(dp(i + 1, j, rem), dp(i, j - 1, rem))
            # Option 2: pair s[i] with s[j] by making them equal
            c1 = ord(s[i]) - ord('a')
            c2 = ord(s[j]) - ord('a')
            dist = min(abs(c1 - c2), 26 - abs(c1 - c2))
            if dist <= rem:
                res = max(res, 2 + dp(i + 1, j - 1, rem - dist))
            return res

        return dp(0, n - 1, k)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        from functools import lru_cache
        n = len(s)

        @lru_cache(maxsize=None)
        def dp(i, j, c):
            if i > j:
                return 0
            if i == j:
                return 1

            # Don't pair s[i] or s[j]
            res = max(dp(i + 1, j, c), dp(i, j - 1, c))

            # Try to pair s[i] and s[j] by making them the same character
            diff = abs(ord(s[i]) - ord(s[j]))
            cost = min(diff, 26 - diff)

            if c >= cost:
                res = max(res, 2 + dp(i + 1, j - 1, c - cost))

            return res

        return dp(0, n - 1, k)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        dist = [[0]*26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                d = abs(a - b)
                dist[a][b] = min(d, 26 - d)

        pair_costs = [[None]*26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                costs = set()
                for c in range(26):
                    costs.add(dist[a][c] + dist[b][c])
                pair_costs[a][b] = sorted(costs)

        s_arr = [ord(c) - 97 for c in s]

        dp = [[None] * n for _ in range(n)]

        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        zero_arr = [0] * (k + 1)

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                dp_i1j = dp[i + 1][j]
                dp_ijm1 = dp[i][j - 1]
                dp_inner = dp[i + 1][j - 1] if i + 1 <= j - 1 else zero_arr
                costs = pair_costs[s_arr[i]][s_arr[j]]

                dp_ij = [0] * (k + 1)
                for kk in range(k + 1):
                    best = dp_i1j[kk]
                    v = dp_ijm1[kk]
                    if v > best:
                        best = v
                    for t in costs:
                        if t > kk:
                            break
                        v = 2 + dp_inner[kk - t]
                        if v > best:
                            best = v
                    dp_ij[kk] = best
                dp[i][j] = dp_ij

        return dp[0][n - 1][k]

