class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def circular_dist(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        # dp[i][j][k] = longest palindromic subsequence in s[i..j] with at most k ops
        # Use 3D DP
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        # Base case: single characters
        for i in range(n):
            for op in range(k + 1):
                dp[i][i][op] = 1

        # Fill by increasing length of subarray
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for op in range(k + 1):
                    # Option 1: skip s[i]
                    best = dp[i + 1][j][op]
                    # Option 2: skip s[j]
                    best = max(best, dp[i][j - 1][op])
                    # Option 3: match s[i] and s[j]
                    cost = circular_dist(s[i], s[j])
                    if cost <= op:
                        if i + 1 <= j - 1:
                            best = max(best, dp[i + 1][j - 1][op - cost] + 2)
                        else:
                            best = max(best, 2)
                    dp[i][j][op] = best

        return dp[0][n - 1][k]

