class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        # dp[kk][i][j] = longest palindromic subseq in s[i..j] with at most kk ops
        dp = [[[0] * n for _ in range(n)] for _ in range(k + 1)]

        for kk in range(k + 1):
            for i in range(n):
                dp[kk][i][i] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                a = ord(s[i]) - ord('a')
                b = ord(s[j]) - ord('a')
                dist = min(abs(a - b), 26 - abs(a - b))
                for kk in range(k + 1):
                    # Skip s[i] or s[j]
                    best = max(dp[kk][i + 1][j], dp[kk][i][j - 1])
                    # Match s[i] and s[j] by changing both to the same char
                    if dist <= kk:
                        inner = dp[kk - dist][i + 1][j - 1] if i + 1 <= j - 1 else 0
                        best = max(best, 2 + inner)
                    dp[kk][i][j] = best

        return dp[k][0][n - 1]

