    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # dp[i][j][t] = longest palindromic subsequence from s[i..j] with at most t operations
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        for i in range(n):
            for t in range(k + 1):
                dp[i][i][t] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                diff = abs(ord(s[i]) - ord(s[j]))
                cost = min(diff, 26 - diff)
                for t in range(k + 1):
                    # Skip s[i] or skip s[j]
                    best = dp[i + 1][j][t]
                    if dp[i][j - 1][t] > best:
                        best = dp[i][j - 1][t]
                    # Match s[i] and s[j] to the same character
                    if cost <= t:
                        inner = dp[i + 1][j - 1][t - cost] if i + 1 <= j - 1 else 0
                        val = 2 + inner
                        if val > best:
                            best = val
                    dp[i][j][t] = best

        return dp[0][n - 1][k]

