    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)

        size = 1
        while size < n:
            size *= 2
        tree = [-1] * (2 * size)

        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def update(pos, val):
            i = size + pos
            tree[i] = val
            i //= 2
            while i >= 1:
                tree[i] = max(tree[2 * i], tree[2 * i + 1])
                i //= 2

        def query_leftmost(threshold):
            if tree[1] < threshold:
                return -1
            i = 1
            while i < size:
                if tree[2 * i] >= threshold:
                    i = 2 * i
                else:
                    i = 2 * i + 1
            result = i - size
            return result if result < n else -1

        unplaced = 0
        for fruit in fruits:
            pos = query_leftmost(fruit)
            if pos == -1:
                unplaced += 1
            else:
