        for x in all_cols:
            if col_reach[x][k] > max_ready:
                max_ready = col_reach[x][k]
        t = max(prev_t, max_ready) + 1
        wave_times.append(t)
        prev_t = t

    removal_time = [0] * N
    for x in all_cols:
        for pos, (y, bid) in enumerate(col_data[x]):
            if pos < len(wave_times):
                removal_time[bid] = wave_times[pos]
