import bisect

def main():
    input_data = sys.stdin.buffer.read().split()
    idx = 0
    def read():
        nonlocal idx
        val = int(input_data[idx])
        idx += 1
        return val

    N = read()
    W = read()
    blocks = []
    for i in range(N):
        x = read()
        y = read()
        blocks.append((x - 1, y, i))

    col_blocks = [[] for _ in range(W)]
    for x, y, i in blocks:
        col_blocks[x].append((y, i))

    a = [0] * N
    arrival_per_col = []
    for x in range(W):
        col_blocks[x].sort()
        cur_max = 0
        arrivals = []
        for k, (y, i) in enumerate(col_blocks[x]):
            val = y - (k + 1)
            if val > cur_max:
                cur_max = val
            a[i] = cur_max
            arrivals.append((cur_max, i))
        arrival_per_col.append(arrivals)

    ptrs = [0] * W
    removal_times = []
    total_blocks = N
    while len(removal_times) < total_blocks:
        mx = -1
        for x in range(W):
            p = ptrs[x]
            if p < len(arrival_per_col[x]):
                av = arrival_per_col[x][p][0]
                if av > mx:
                    mx = av
        if mx < 0:
            break
        t = mx + 1
        if not removal_times or t > removal_times[-1]:
            removal_times.append(t)
        else:
            removal_times[-1] = t
        for x in range(W):
            while ptrs[x] < len(arrival_per_col[x]) and arrival_per_col[x][ptrs[x]][0] <= t:
                ptrs[x] += 1

    removal_time_of_block = [10**18] * N
    for x in range(W):
        for k in range(len(col_blocks[x])):
            block_idx = col_blocks[x][k][1]
            axk = a[block_idx]
            j = bisect.bisect_left(removal_times, axk)
            if j < len(removal_times):
                removal_time_of_block[block_idx] = removal_times[j]

    Q = read()
    results = []
    for _ in range(Q):
        T = read()
        A = read() - 1
        if removal_time_of_block[A] <= T:
            results.append("No")
        else:
            results.append("Yes")

    sys.stdout.write('\n'.join(results) + '\n')

