def solve():
    input = sys.stdin.buffer.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    W = int(input[idx]); idx += 1

    col_blocks = defaultdict(list)
    for i in range(N):
        x = int(input[idx]); idx += 1
        y = int(input[idx]); idx += 1
        col_blocks[x].append((y, i + 1))

    for x in col_blocks:
        col_blocks[x].sort()

    col_counts = {x: len(v) for x, v in col_blocks.items()}
    K = min(col_counts.values())

    # M[i] = max over columns of (i-th block height from bottom) - 1, 0-indexed
    M = [0] * K
    for i in range(K):
        max_h = 0
        for x in col_blocks:
            if i < len(col_blocks[x]):
                h = col_blocks[x][i][0]
                if h > max_h:
                    max_h = h
        M[i] = max_h - 1

    # r[i] = removal time of i-th layer (0-indexed)
    r = [0] * K
    r[0] = M[0]
    for i in range(1, K):
        r[i] = max(r[i-1] + 1, M[i])

    # For each block, compute its rank from bottom in its column
    block_rank = [0] * (N + 1)
    for x, blocks in col_blocks.items():
        for rank, (h, block_id) in enumerate(blocks):
            block_rank[block_id] = rank + 1  # 1-indexed rank

    Q = int(input[idx]); idx += 1
    out = []
    for _ in range(Q):
        T = int(input[idx]); idx += 1
        A = int(input[idx]); idx += 1
        rank = block_rank[A]
        if rank > K:
            out.append("Yes")
        else:
            if T < r[rank - 1]:
                out.append("Yes")
            else:
                out.append("No")

    print('\n'.join(out))

