    block_col = [0] * (N + 1)
    block_idx_in_col = [0] * (N + 1)

    for i in range(1, N + 1):
        x, y = map(int, input().split())
        blocks_by_col[x - 1].append((y, i))
        block_col[i] = x - 1

    for c in range(W):
        blocks_by_col[c].sort()
        for idx in range(len(blocks_by_col[c])):
            block_idx_in_col[blocks_by_col[c][idx][1]] = idx

    clear_times = []
    idx = [0] * W
    total_blocks = [len(blocks_by_col[c]) for c in range(W)]

    while all(idx[c] < total_blocks[c] for c in range(W)):
        t = 0
        for c in range(W):
            cidx = idx[c]
            h = blocks_by_col[c][cidx][1]
            if cidx == 0:
                arrival = h - cidx
            else:
                arrival = max(h - cidx, clear_times[cidx - 1] + 1)
            if arrival > t:
                t = arrival
        clear_times.append(t)
        for c in range(W):
            idx[c] += 1

    Q = int(input())
    out = []
    for q in range(Q):
        T, A = map(int, input().split())
        c = block_col[A]
        i = block_idx_in_col[A]
        m = total_blocks[c]

        if i + 1 < m:
            out.append("Yes")
        else:
            if i < len(clear_times):
                if T < clear_times[i]:
                    out.append("Yes")
                else:
                    out.append("No")
            else:
                out.append("Yes")

    print('\n'.join(out))

