class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        pairs = sorted([(nums1[i], nums2[i], i) for i in range(n)])

        answer = [0] * n
        import heapq
        heap = []
        current_sum = 0

        i = 0
        while i < n:
            j = i
            while j < n and pairs[j][0] == pairs[i][0]:
                j += 1

            for t in range(i, j):
                answer[pairs[t][2]] = current_sum

            for t in range(i, j):
                val = pairs[t][1]
                if len(heap) < k:
                    heapq.heappush(heap, val)
                    current_sum += val
                elif val > heap[0]:
                    current_sum -= heapq.heappop(heap)
                    heapq.heappush(heap, val)
                    current_sum += val

            i = j

        return answer

