class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        chars = [ord(c) - ord('a') for c in caption]

        # prefix[c][i] = sum of |chars[t] - c| for t in [0, i)
        prefix = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(n):
                prefix[c][i + 1] = prefix[c][i] + abs(chars[i] - c)

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[n] = 0

        # suff_min[c][i] = min of (prefix[c][j] + dp[j]) for j in [i, n]
        suff_min = [[0] * (n + 2) for _ in range(26)]
        for c in range(26):
            suff_min[c][n] = prefix[c][n] + dp[n]
            for i in range(n - 1, -1, -1):
                suff_min[c][i] = min(prefix[c][i] + dp[i], suff_min[c][i + 1])

        # Compute dp backwards
        for i in range(n - 1, -1, -1):
            if i + 3 <= n:
                best = INF
                for c in range(26):
                    val = -prefix[c][i] + suff_min[c][i + 3]
                    if val < best:
                        best = val
                dp[i] = best

        if dp[0] == INF:
            return ""

        # Precompute first character of optimal string from each position
        first_char = [0] * (n + 1)
        first_char[n] = 26  # sentinel (larger than any real char)

        for i in range(n - 1, -1, -1):
            if i + 3 > n:
                first_char[i] = 26
                continue
            for c in range(26):
                if -prefix[c][i] + suff_min[c][i + 3] == dp[i]:
                    first_char[i] = c
                    break

        # Reconstruct
        result = []
        i = 0
        while i < n:
            placed = False
            for c in range(26):
                if -prefix[c][i] + suff_min[c][i + 3] != dp[i]:
                    continue
                # Find largest j in [i+3, n] with prefix[c][j] + dp[j] == suff_min[c][i+3]
                best_j = -1
                for j in range(i + 3, n + 1):
                    if prefix[c][j] + dp[j] == suff_min[c][i + 3]:
                        best_j = j
                if best_j >= 0:
                    result.append(chr(ord('a') + c) * (best_j - i))
                    i = best_j
                    placed = True
                    break
            if not placed:
                return ""

        return ''.join(result)

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = float('inf')

        # prefix_cost[c][i] = sum_{k=0}^{i-1} |ord(caption[k]) - (97+c)|
        pc = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            ch = 97 + c
            for i in range(n):
                pc[c][i + 1] = pc[c][i] + abs(ord(caption[i]) - ch)

        def seg_cost(c, a, b):
            """Cost to make positions a..b-1 all char c"""
            return pc[c][b] - pc[c][a]

        # Forward DP
        fwd = [[INF] * 26 for _ in range(n + 1)]
        for c in range(26):
            fwd[0][c] = 0

        run_min = [0.0] * 26
        for i in range(3, n + 1):
            j = i - 3
            if any(fwd[j][c] < INF for c in range(26)):
                m1, m2, m1c = INF, INF, -1
                for c in range(26):
                    v = fwd[j][c]
                    if v < m1:
                        m2, m1, m1c = m1, v, c
                    elif v < m2:
                        m2 = v
                for c in range(26):
                    best = m1 if m1c != c else m2
                    val = best - pc[c][j]
                    if val < run_min[c]:
                        run_min[c] = val
            for c in range(26):
                if run_min[c] < INF:
                    fwd[i][c] = pc[c][i] + run_min[c]

        total_cost = min(fwd[n])
        if total_cost == INF:
            return ""

        # Backward DP
        bwd = [[INF] * 26 for _ in range(n + 1)]
        for c in range(26):
            bwd[n][c] = 0

        rm_b = [[INF] * 26 for _ in range(26)]
        for c_last in range(26):
            for c in range(26):
                rm_b[c_last][c] = 0.0
        for i in range(n - 3, -1, -1):
            has_valid = any(bwd[i + 3][c] < INF for c in range(26))
            if has_valid:
                for c_last in range(26):
                    m1, m2, m1c = INF, INF, -1
                    for c in range(26):
                        v = bwd[i + 3][c]
                        if v < m1:
                            m2, m1, m1c = m1, v, c
                        elif v < m2:
                            m2 = v
                    for c in range(26):
                        if c == c_last:
                            continue
                        best = m1 if m1c != c else m2
                        if best < INF:
                            val = best - pc[c][i + 3]
                            if val < rm_b[c_last][c]:
                                rm_b[c_last][c] = val
            for c in range(26):
                bwd[i][c] = pc[c][i] + min(rm_b[c][cl] for cl in range(26) if cl != c) if any(rm_b[c][cl] < INF for cl in range(26) if cl != c) else INF

        # Greedy reconstruction
        res = []
        i = 0
        prev_c = -1
        while i < n:
            placed = False
            for c in range(26):
                if c == prev_c:
                    continue
                lo = i
                hi = n - 2
                if hi < lo:
                    continue
                best_se = -1
                while lo <= hi:
                    mid = (lo + hi) // 2
                    se = i + mid
                    cost_seg = seg_cost(c, i, se + 1)
                    rem = se + 1
                    if rem == n:
                        rem_cost = 0
                    else:
                        rem_cost = min((bwd[rem][cc] for cc in range(26) if cc != c), default=INF)
                    total = cost_seg + rem_cost
                    if total <= total_cost:
                        best_se = se
                        hi = mid - 1
                    else:
                        lo = mid + 1
                if best_se >= 0:
                    se = best_se
                    res.extend([chr(97 + c)] * (se - i + 1))
                    prev_c = c
                    i = se + 1
                    placed = True
                    break
            if not placed:
                return ""

        return ''.join(res)

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # Precompute prefix sums for each character
        # prefix[c][i] = sum of |caption[k] - c| for k in [0, i)
        prefix = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(n):
                prefix[c][i + 1] = prefix[c][i] + abs(ord(caption[i]) - ord('a') - c)

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[n] = 0

        # suffix_min[c][i] = min of (prefix[c][j] + dp[j]) for j in [i, n]
        suffix_min = [[INF] * (n + 2) for _ in range(26)]
        for c in range(26):
            suffix_min[c][n] = prefix[c][n] + dp[n]

        for i in range(n - 1, -1, -1):
            dp[i] = INF
            for c in range(26):
                if i + 3 <= n:
                    val = suffix_min[c][i + 3] - prefix[c][i]
                    if val < dp[i]:
                        dp[i] = val
            for c in range(26):
                suffix_min[c][i] = min(prefix[c][i] + dp[i], suffix_min[c][i + 1])

        if dp[0] == INF:
            return ""

        # Precompute first_char[i] = first character of lexicographically smallest optimal solution from i
        first_char = [-1] * (n + 1)
        first_char[n] = -1

        for i in range(n - 1, -1, -1):
            best_c = 26
            for c in range(26):
                found = False
                for L in range(3, n - i + 1):
                    j = i + L
                    if prefix[c][j] - prefix[c][i] + dp[j] == dp[i]:
                        found = True
                        break
                if found and c < best_c:
                    best_c = c
            first_char[i] = best_c

        # Reconstruction
        result = []
        i = 0
        while i < n:
            placed = False
            for c in range(26):
                valid_lengths = []
                for L in range(3, n - i + 1):
                    j = i + L
                    if prefix[c][j] - prefix[c][i] + dp[j] == dp[i]:
                        valid_lengths.append(L)
                if not valid_lengths:
                    continue
                # Choose best L
                if len(valid_lengths) == 1:
                    best_L = valid_lengths[0]
                else:
                    # Find the valid L that gives lexicographically smallest result
                    # For L, the char at position i+L in result is 'c' if L < max_valid, 
                    # or first_char[i+L] if L is the actual group length
                    # Compare: for L_a < L_b, at position i+L_a: first_char[i+L_a] vs 'c'
                    # We want to find the "threshold"
                    # If first_char[i+L] < c for some valid L, pick smallest such L
                    # Otherwise pick the largest valid L
                    best_L = valid_lengths[0]
                    for L in valid_lengths:
                        j = i + L
                        if j < n:
                            if first_char[j] < c:
                                best_L = L
                                break
                    else:
                        best_L = valid_lengths[-1]

                result.extend([chr(ord('a') + c)] * best_L)
                i += best_L
                placed = True
                break
            if not placed:
                return ""

        return ''.join(result)

