        vals = [ord(c) - ord('a') for c in caption]
        INF = float('inf')

        # P[c][i] = sum of |vals[k] - c| for k in 0..i-1
        P = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(1, n + 1):
                P[c][i] = P[c][i - 1] + abs(vals[i - 1] - c)

        # Forward DP: dp[i] = min cost for prefix [0, i)
        dp = [INF] * (n + 1)
        dp[0] = 0
        m = [INF] * 26

        for i in range(1, n + 1):
            if i - 3 >= 0 and dp[i - 3] < INF:
                for c in range(26):
                    val = dp[i - 3] - P[c][i - 3]
                    if val < m[c]:
                        m[c] = val
            if i >= 3:
                best = INF
                for c in range(26):
                    if m[c] < INF:
                        cost = P[c][i] + m[c]
                        if cost < best:
                            best = cost
                dp[i] = best

        if dp[n] >= INF:
            return ""

        # Backward DP: suffix[i] = min cost to fill [i, n)
        suffix = [INF] * (n + 1)
        suffix[n] = 0
        M = [INF] * 26

        for i in range(n - 1, -1, -1):
            j = i + 3
            if j <= n and suffix[j] < INF:
                for c in range(26):
                    val = suffix[j] + P[c][j]
                    if val < M[c]:
                        M[c] = val
            if i + 3 <= n:
                best = INF
                for c in range(26):
                    if M[c] < INF:
                        cost = -P[c][i] + M[c]
                        if cost < best:
                            best = cost
                suffix[i] = best

