        result = []
        pos = 0
        acc = 0
        while pos < n:
            found = False
            for c in range(26):
                if found:
                    break
                for L in range(3, n - pos + 1):
                    e = pos + L
                    seg_cost = P[c][e] - P[c][pos]
                    remaining = suffix[e]
