        return ''.join(result)

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        chars = [ord(c) - ord('a') for c in caption]

        # Precompute prefix costs: pc[c][i] = sum of |chars[k] - c| for k in [0, i)
        pc = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(n):
                pc[c][i + 1] = pc[c][i] + abs(chars[i] - c)

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0

        # best[c] = running min of dp[j] - pc[c][j] for valid j
        best = [INF] * 26

        for i in range(3, n + 1):
            # add j = i - 3 to running minimums
            j = i - 3
            if dp[j] < INF:
                for c in range(26):
                    val = dp[j] - pc[c][j]
                    if val < best[c]:
                        best[c] = val
            # compute dp[i]
            for c in range(26):
                if best[c] < INF:
                    cost = pc[c][i] + best[c]
                    if cost < dp[i]:
                        dp[i] = cost

        if dp[n] >= INF:
            return ""

        # Greedy forward reconstruction for lexicographically smallest
        result = []
        start = 0
        rem_target = dp[n]

        while start < n:
            max_end = n
            chosen_c = -1
            chosen_end = -1

            for c in range(26):  # try smallest char first
                found = False
                for end in range(max_end, start + 2, -1):  # try largest end first
                    L = end - start
                    if L >= 3:
                        seg_cost = pc[c][end] - pc[c][start]
                        rem_after = rem_target - seg_cost
                        if rem_after < 0:
                            break  # further (smaller end) won't help for this c
                        rem_len = end - (start + L)  # = n - end
                        if rem_after == 0 and rem_len == 0:
                            chosen_c = c
                            chosen_end = end
                            found = True
                            break
                        elif rem_after > 0 and rem_len >= 3:
                            # check feasibility via suffix DP
                            feasible = False
                            for c2 in range(26):
                                if pc[c2][n] - pc[c2][end] <= rem_after:
                                    feasible = True
                                    break
                            if feasible:
                                chosen_c = c
                                chosen_end = end
                                found = True
                                break
                if found:
                    break

            if chosen_c == -1:
                return ""

            result.append(chr(chosen_c + ord('a')) * (chosen_end - start))
            rem_target -= pc[chosen_c][chosen_end] - pc[chosen_c][start]
            start = chosen_end

        return ''.join(result)

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        A = [ord(c) - ord('a') for c in caption]

        # ps[c][i] = sum of |A[k] - c| for k in [0, i)
        ps = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(1, n + 1):
                ps[c][i] = ps[c][i-1] + abs(A[i-1] - c)

        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[n] = 0
        best_from = [[INF] * 26 for _ in range(n + 2)]

        for i in range(n - 1, -1, -1):
            if i + 3 <= n:
                for c in range(26):
                    best_from[i][c] = min(ps[c][i+3] + dp[i+3], best_from[i+1][c])
                    val = best_from[i][c] - ps[c][i]
                    if val < dp[i]:
                        dp[i] = val

        if dp[0] >= INF:
            return ""

        total = [0] * (n + 1)
        for i in range(1, n + 1):
            total[i] = total[i-1] + A[i-1]

        def seg_cost(c, l, r):
            # cost of assigning char c to positions [l, r)
            s = 0
            for k in range(l, r):
                s += abs(A[k] - c)
            return s

        result = []
        pos = 0
        while pos < n:
            found = False
            for c in range(26):
                if pos + 3 > n:
                    break
                target = dp[pos] + ps[c][pos]
                if best_from[pos][c] == target:
                    # find the largest j >= pos+3 with ps[c][j] + dp[j] == target
                    best_j = -1
                    for j in range(n, pos + 2, -1):
                        if dp[j] < INF and ps[c][j] + dp[j] == target:
                            best_j = j
                            break
                    if best_j >= pos + 3:
                        result.append(chr(ord('a') + c) * (best_j - pos))
                        pos = best_j
                        found = True
                        break
            if not found:
                return ""

        return ''.join(result)

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = float('inf')

        # Precompute prefix sums: pref[c][i] = sum of |caption[k]-c| for k in [0, i)
        pref = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(1, n + 1):
                pref[c][i] = pref[c][i-1] + abs(ord(caption[i-1]) - 97 - c)

        # Forward DP
        dp_fwd = [INF] * (n + 1)
        dp_fwd[0] = 0
        min_fwd = [INF] * 26

        for i in range(3, n + 1):
            j = i - 3
            if dp_fwd[j] < INF:
                for c in range(26):
                    val = dp_fwd[j] - pref[c][j]
                    if val < min_fwd[c]:
                        min_fwd[c] = val
            best = INF
            for c in range(26):
                if min_fwd[c] < INF:
                    val = pref[c][i] + min_fwd[c]
                    if val < best:
                        best = val
            dp_fwd[i] = best

        if dp_fwd[n] >= INF:
            return ""

        # Backward DP
        dp_bwd = [INF] * (n + 1)
        dp_bwd[n] = 0
        min_bwd = [INF] * 26

        for i in range(n - 3, -1, -1):
            end = i + 3
            if dp_bwd[end] < INF:
                for c in range(26):
                    val = pref[c][end] + dp_bwd[end]
                    if val < min_bwd[c]:
                        min_bwd[c] = val
            best = INF
            for c in range(26):
                if min_bwd[c] < INF:
                    val = -pref[c][i] + min_bwd[c]
                    if val < best:
                        best = val
            dp_bwd[i] = best

        # Greedy reconstruction
        result = []
        cost_so_far = 0
        pos = 0

        while pos < n:
            placed = False
            for c in range(26):
                if placed:
                    break
                for end in range(pos + 3, n + 1):
                    rem = n - end
                    if rem != 0 and rem < 3:
                        continue
                    if dp_bwd[end] >= INF:
                        continue
                    seg_cost = pref[c][end] - pref[c][pos]
                    if cost_so_far + seg_cost + dp_bwd[end] == dp_fwd[n]:
                        result.extend([chr(97 + c)] * (end - pos))
                        cost_so_far += seg_cost
                        pos = end
                        placed = True
                        break

        return ''.join(result)

