class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        arr = [ord(c) - ord('a') for c in caption]
        INF = float('inf')

        prefix = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i in range(n):
                prefix[c][i + 1] = prefix[c][i] + abs(arr[i] - c)

        def segment_cost(i, j, c):
            return prefix[c][j] - prefix[c][i]

        def best_char_and_cost(i, j):
            best_c = 0
            best_cost = segment_cost(i, j, 0)
            for c in range(1, 26):
                cost = segment_cost(i, j, c)
                if cost < best_cost:
                    best_cost = cost
                    best_c = c
            return best_c, best_cost

        dp_cost = [INF] * (n + 1)
        dp_char = [0] * n
        dp_end = [0] * n
        dp_cost[n] = 0

        for i in range(n - 1, -1, -1):
            best_total = INF
            best_c = 0
            best_j = -1
            for j in range(i + 3, n + 1):
                c, seg_cost = best_char_and_cost(i, j)
                total = seg_cost + dp_cost[j]
                if total < best_total:
                    best_total = total
                    best_c = c
                    best_j = j
                elif total == best_total:
                    if c < best_c:
                        best_c = c
                        best_j = j
                    elif c == best_c and j < best_j:
                        best_j = j
            if best_j != -1:
                dp_cost[i] = best_total
                dp_char[i] = best_c
                dp_end[i] = best_j

        if dp_cost[0] == INF:
            return ""

        result = []
        i = 0
        while i < n:
            c = dp_char[i]
            j = dp_end[i]
            result.append(chr(ord('a') + c) * (j - i))
            i = j
        return ''.join(result)

import sys
sys.setrecursionlimit(3000000)

def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    contests = []
    for _ in range(N):
        L = int(data[idx]); R = int(data[idx + 1]); idx += 2
        contests.append((L, R))
    Q = int(data[idx]); idx += 1
    queries = [int(data[idx + i]) for i in range(Q)]

    MAX = 500000
    size = 1
    while size < MAX:
        size <<= 1

    tree_min = [0] * (4 * MAX)
    tree_max = [0] * (4 * MAX)
    lazy = [0] * (4 * MAX)

    def build(node, l, r):
        if l == r:
            tree_min[node] = l
            tree_max[node] = l
            return
        mid = (l + r) >> 1
        build(node << 1, l, mid)
        build(node << 1 | 1, mid + 1, r)
        tree_min[node] = tree_min[node << 1]
        tree_max[node] = tree_max[node << 1 | 1]

    def push(node):
        lv = lazy[node]
        if lv:
            lc = node << 1
            rc = lc | 1
            tree_min[lc] += lv
            tree_max[lc] += lv
            lazy[lc] += lv
            tree_min[rc] += lv
            tree_max[rc] += lv
            lazy[rc] += lv
            lazy[node] = 0

    def range_add(node, l, r, ql, qr, val):
        if qr < l or r < ql:
            return
        if ql <= l and r <= qr:
            tree_min[node] += val
            tree_max[node] += val
            lazy[node] += val
            return
        push(node)
        mid = (l + r) >> 1
        range_add(node << 1, l, mid, ql, qr, val)
        range_add(node << 1 | 1, mid + 1, r, ql, qr, val)
        tree_min[node] = tree_min[node << 1]
        tree_max[node] = tree_max[node << 1 | 1]

    def find_first_ge(node, l, r, target):
        if tree_max[node] < target:
            return -1
        if l == r:
            return l
        push(node)
        mid = (l + r) >> 1
        if tree_max[node << 1] >= target:
            return find_first_ge(node << 1, l, mid, target)
        return find_first_ge(node << 1 | 1, mid + 1, r, target)

    def find_last_le(node, l, r, target):
        if tree_min[node] > target:
            return -1
        if l == r:
            return l
        push(node)
        mid = (l + r) >> 1
        if tree_min[node << 1 | 1] <= target:
            return find_last_le(node << 1 | 1, mid + 1, r, target)
        return find_last_le(node << 1, l, mid, target)

    def point_query(node, l, r, pos):
        if l == r:
            return tree_min[node]
        push(node)
        mid = (l + r) >> 1
        if pos <= mid:
            return point_query(node << 1, l, mid, pos)
        return point_query(node << 1 | 1, mid + 1, r, pos)

    build(1, 1, MAX)

    for L, R in contests:
        a = find_first_ge(1, 1, MAX, L)
        if a == -1:
            continue
        b = find_last_le(1, 1, MAX, R)
        if b == -1 or a > b:
            continue
        range_add(1, 1, MAX, a, b, 1)

    out = []
    for X in queries:
        out.append(str(point_query(1, 1, MAX, X)))
    sys.stdout.write('\n'.join(out) + '\n')

solve()

