    tree_max = array('i', [0]) * (2 * size)
    lazy = array('i', [0]) * (2 * size)

    for i in range(MAXV):
        tree_min[size + i] = i + 1
        tree_max[size + i] = i + 1
    for i in range(MAXV, size):
        tree_min[size + i] = INF
        tree_max[size + i] = -INF
    for i in range(size - 1, 0, -1):
        tree_min[i] = tree_min[2*i] if tree_min[2*i] < tree_min[2*i+1] else tree_min[2*i+1]
        tree_max[i] = tree_max[2*i] if tree_max[2*i] > tree_max[2*i+1] else tree_max[2*i+1]

    def apply_node(v, val):
        tree_min[v] += val
        tree_max[v] += val
        lazy[v] += val

    def push(v):
        lz = lazy[v]
        if lz:
            apply_node(2*v, lz)
            apply_node(2*v+1, lz)
            lazy[v] = 0

    def range_add(v, tl, tr, l, r, val):
        if l > r:
            return
        if l == tl and r == tr:
            apply_node(v, val)
            return
        push(v)
        tm = (tl + tr) >> 1
        if r <= tm:
            range_add(2*v, tl, tm, l, r, val)
        elif l > tm:
            range_add(2*v+1, tm+1, tr, l, r, val)
        else:
            range_add(2*v, tl, tm, l, tm, val)
            range_add(2*v+1, tm+1, tr, tm+1, r, val)
        tree_min[v] = tree_min[2*v] if tree_min[2*v] < tree_min[2*v+1] else tree_min[2*v+1]
        tree_max[v] = tree_max[2*v] if tree_max[2*v] > tree_max[2*v+1] else tree_max[2*v+1]

    def find_first_ge(v, tl, tr, target):
        if tree_max[v] < target:
            return -1
        if tl == tr:
            return tl if tl < MAXV else -1
        push(v)
        tm = (tl + tr) >> 1
        res = find_first_ge(2*v, tl, tm, target)
        if res != -1:
            return res
        return find_first_ge(2*v+1, tm+1, tr, target)

    def find_last_le(v, tl, tr, target):
        if tree_min[v] > target:
            return -1
        if tl == tr:
            return tl if tl < MAXV else -1
        push(v)
        tm = (tl + tr) >> 1
        res = find_last_le(2*v+1, tm+1, tr, target)
        if res != -1:
            return res
        return find_last_le(2*v, tl, tm, target)

    def point_query(pos):
        return _ptq(1, 0, size - 1, pos)

    def _ptq(v, tl, tr, pos):
        if tl == tr:
            return tree_min[v]
        push(v)
        tm = (tl + tr) >> 1
        if pos <= tm:
            return _ptq(2*v, tl, tm, pos)
        else:
            return _ptq(2*v+1, tm+1, tr, pos)

    for l, r in contests:
        left = find_first_ge(1, 0, size - 1, l)
        if left == -1:
            continue
        right = find_last_le(1, 0, size - 1, r)
        if right == -1 or left > right:
            continue
        range_add(1, 0, size - 1, left, right, 1)

    out = []
    for x in queries:
        out.append(str(point_query(x - 1)))
    sys.stdout.write('\n'.join(out) + '\n')

