    for i in xs_sorted:
        if queries[i] not in seen:
            seen.add(queries[i])
            unique_xs.append(queries[i])

    results = {}

    def run_sim(x):
        c = 0
        for i in range(N):
            if L[i] <= x + c <= R[i]:
                c += 1
        return x + c

