        res = run_sim(unique_xs[mid])
        results[unique_xs[mid]] = res
        if lo < mid:
            dc(lo, mid - 1)
        if mid < hi:
            dc(mid + 1, hi)

    dc(0, len(unique_xs) - 1)

    out = []
    for i in range(Q):
        out.append(str(results[queries[i]]))
