                    a = Sp - S
                    if s[i] == '0':
                        c_vals = [a]
                    else:
                        c_vals = [a, a + 1]
                    for c in c_vals:
                        if c < -1 or c > 2:
                            continue
                        bit = 0 if c == 1 else 1
                        new_mask = mask | (1 << bit)
                        new_dp[sp][new_mask] = (new_dp[sp][new_mask] + val) % MOD
        dp = new_dp

    case2 = dp[0][0] + dp[0][3]  # must end at partial sum 0 (index 0)

    # Double: all a_i = 0, c_i = 0 for s_i=0, c_i in {0,1} for s_i=1
    # Achievable: c_i=0 is always valid, so K+1 distinct sequences
    double = K + 1

    ans = (case1 + case2 - double) % MOD
    print(ans)

