    N = int(input_data[0])
    s = input_data[1].strip()
    k = sum(1 for c in s if c == '1')
    MOD = 998244353

    if k == 0:
        print(pow(2, N, MOD))
        return

    # dp[(a_offset, b_sum)] where a_offset in {0,1,2} maps to a_val in {-1,0,1}
    dp = {(1, 0): 1}

    for i in range(N):
        ndp = {}
        if s[i] == '0':
            for (ao, bs), cnt in dp.items():
                ndp[(1, bs)] = (ndp.get((1, bs), 0) + cnt) % MOD
        else:
            for (ao, bs), cnt in dp.items():
                # Option A: a_i=0, b_i=0
                ndp[(1, bs)] = (ndp.get((1, bs), 0) + cnt) % MOD
                # Option B+: a_i=+1, b_i=+1
                if bs + 1 <= k:
                    ndp[(2, bs + 1)] = (ndp.get((2, bs + 1), 0) + cnt) % MOD
                # Option B-: a_i=-1, b_i=-1
                if bs - 1 >= 0:
                    ndp[(0, bs - 1)] = (ndp.get((0, bs - 1), 0) + cnt) % MOD
        dp = ndp

    ans = sum(dp.values()) % MOD
    print(ans)

