    M = int(data[idx]); idx += 1
    A = int(data[idx]); idx += 1
    B = int(data[idx]); idx += 1

    intervals = []
    for _ in range(M):
        L = int(data[idx]); idx += 1
        R = int(data[idx]); idx += 1
        intervals.append((L, R))

    regions = []
    prev_end = 1
    for L, R in intervals:
        if prev_end <= L - 1:
            regions.append((prev_end, L - 1))
        prev_end = R + 1
    if prev_end <= N:
        regions.append((prev_end, N))

    if not regions or regions[0][0] != 1:
        print("No")
        return

    reachable = {1}
    all_from = None

    for ri, (rl, rr) in enumerate(regions):
        if ri > 0:
            prev_rr = regions[ri - 1][1]
            L_bad = intervals[ri - 1][0]
            R_bad = intervals[ri - 1][1]
            if all_from is not None:
                lo = max(all_from, R_bad + 1 - B, prev_rr - B + 1)
                entry = set(range(max(lo, rl), min(rr, R_bad + B) + 1))
                entry = {x for x in entry if rl <= x <= rr}
            else:
                entry = set()
                for pos in reachable:
                    lo_j = max(A, R_bad + 1 - pos)
                    hi_j = min(B, rr - pos)
                    if lo_j <= hi_j:
                        for x in range(pos + lo_j, pos + hi_j + 1):
                            if rl <= x <= rr:
                                entry.add(x)
            if not entry:
                print("No")
                return
            reachable = entry
            all_from = None

        if all_from is not None:
            if rr >= all_from:
                reachable = set(range(max(all_from, rr - 2*B), rr + 1))
            continue

        changed = True
        while changed:
            changed = False
            newly = set()
            for pos in reachable:
                for x in range(pos + A, min(pos + B, rr) + 1):
                    if x not in reachable:
                        newly.add(x)
            if newly:
                reachable |= newly
                changed = True
            if len(reachable) > 200:
                break

        positions = sorted(reachable)
        for i in range(len(positions) - B):
            if positions[i + B - 1] - positions[i] == B - 1:
                all_from = positions[i] + A
                break

        if all_from is None:
            reached = max(reachable) if reachable else rl - 1
            if reached + B < rr:
                pass
            tail_start = max(rl, rr - 2 * B)
            reachable = {x for x in reachable if x >= tail_start}

        if all_from is not None and ri == len(regions) - 1:
            if N >= all_from:
                print("Yes")
                return

    if all_from is not None:
        print("Yes")
    elif N in reachable:
        print("Yes")
