def solve():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    A = int(data[idx]); idx += 1
    B = int(data[idx]); idx += 1

    intervals = []
    for _ in range(M):
        L = int(data[idx]); idx += 1
        R = int(data[idx]); idx += 1
        intervals.append((L, R))

    # Check if any bad interval is too long to jump over
    for L, R in intervals:
        if R - L + 1 >= B:
            print("No")
            return

    # Compute threshold for long regions
    if A == B:
        LONG_THRESHOLD = B
    else:
        LONG_THRESHOLD = ((A - 1) + (B - A) - 1) // (B - A) * A + B

    prev_end = 1  # We start at position 1, which is reachable

    for L, R in intervals:
        S = prev_end + 1
        E = L - 1

        if S > E:
            # No free region before this bad interval
            # We must jump directly from prev_end
            if prev_end + B <= R:
                print("No")
                return
            start = R + 1
            end = min(prev_end + B, N)
            prev_end = end
            continue

        # Free region [S, E] exists
        window_start = max(E - B + 1, S)

        if E - S + 1 >= LONG_THRESHOLD:
            # Long region: if we can reach S, all positions [S+LONG_THRESHOLD, E] are reachable
            for x in range(max(window_start, S + LONG_THRESHOLD), E + 1):
                if x + A > R:
                    prev_end = min(x + B, N)
                    break
            else:
                print("No")
                return
        else:
            # Short region: compute reachability exactly
            size = E - S + 1
            reachable = [False] * (size + 1)
            reachable[0] = True  # position S is reachable
            for i in range(1, size + 1):
                for j in range(A, B + 1):
                    if i - j >= 0 and reachable[i - j]:
                        reachable[i] = True
                        break

            for x in range(max(window_start, S), E + 1):
                if reachable[x - S] and x + A > R:
                    prev_end = min(x + B, N)
                    break
            else:
                print("No")
                return

    # After all bad intervals, check if N is reachable
    final_S = prev_end + 1
    if N == prev_end:
        print("Yes")
        return
    if final_S > N:
        print("No")
        return

    final_E = N
    if final_E - final_S + 1 >= LONG_THRESHOLD:
        if N >= final_S + LONG_THRESHOLD:
            print("Yes")
        else:
            print("No")
    else:
        size = final_E - final_S + 1
        reachable = [False] * (size + 1)
        reachable[0] = True
        for i in range(1, size + 1):
            for j in range(A, B + 1):
                if i - j >= 0 and reachable[i - j]:
                    reachable[i] = True
                    break
        print("Yes" if reachable[N - final_S] else "No")

