import heapq

def solve():
    input_data = sys.stdin.buffer.read().split()
    ptr = 0
    N = int(input_data[ptr]); ptr += 1
    W_raw = list(input_data[ptr:ptr+N]); ptr += N
    W = [0] + [int(x) for x in W_raw]
    L = [0]*(N+1)
    R = [0]*(N+1)
    for i in range(1, N+1):
        L[i] = int(input_data[ptr]); ptr += 1
        R[i] = int(input_data[ptr]); ptr += 1
    Q = int(input_data[ptr]); ptr += 1
    queries = []
    for _ in range(Q):
        s = int(input_data[ptr]); ptr += 1
        t = int(input_data[ptr]); ptr += 1
        queries.append((s, t))

    # Find interval graph connected components
    sorted_idx = sorted(range(1, N+1), key=lambda i: (L[i], R[i]))
    comp = [0]*(N+1)
    k = 0
    cur_max_r = -1
    for i in sorted_idx:
        if L[i] > cur_max_r:
            k += 1
            cur_max_r = R[i]
        else:
            if R[i] > cur_max_r:
                cur_max_r = R[i]
        comp[i] = k

    if k >= 2:
        min_per_comp = {}
        for c in range(1, k+1):
            min_per_comp[c] = float('inf')
        for i in range(1, N+1):
            c = comp[i]
            if W[i] < min_per_comp[c]:
                min_per_comp[c] = W[i]

        results = []
        for s, t in queries:
            cs, ct = comp[s], comp[t]
            if cs != ct:
                results.append(str(W[s] + W[t]))
            else:
                if R[s] < L[t] or R[t] < L[s]:
                    results.append(str(W[s] + W[t]))
                else:
                    best = float('inf')
                    for c in range(1, k+1):
                        if c != cs and min_per_comp[c] < best:
                            best = min_per_comp[c]
                    results.append(str(W[s] + W[t] + best))
        sys.stdout.write('\n'.join(results) + '\n')
        return

    # k == 1: Specialized Dijkstra from min-weight vertex
    pts = sorted(set(list(L[1:]) + list(R[1:])))
    pidx = {v: i+1 for i, v in enumerate(pts)}
    M = len(pts)

    sums = [0]*(M+2)
    last = [0]*(M+1)
    INF = float('inf')

    def seg_update(i, val):
        while i <= M:
            sums[i] += val
            i += i & (-i)

    def seg_ql(i, j):
        if i > j: return 0
        res = 0
        i += 1; j += 1
        while i < j:
            if i & 1: res += sums[i]; i += 1
            if j & 1: j -= 1; res += sums[j]
            i >>= 1; j >>= 1
        return res

    def seg_argmin(i, j):
        if i > j: return (INF, -1)
        rv = INF; rp = -1
        i += 1; j += 1
        while i < j:
            if i & 1:
                if last[i] < rv: rv = last[i]; rp = i
                i += 1
            if j & 1:
                j -= 1
                if last[j] < rv: rv = last[j]; rp = j
            i >>= 1; j >>= 1
        return (rv, rp)

    intervals_by = [[] for _ in range(M+1)]
    for i in range(1, N+1):
        li = pidx[L[i]]; ri = pidx[R[i]]
        intervals_by[li].append((ri, i))

    min_w = INF; src = 1
    for i in range(1, N+1):
        if W[i] < min_w:
            min_w = W[i]; src = i

    dist = [INF]*(N+1)
    dist[src] = W[src]
    visited = [False]*(N+1)
    visited[src] = True
    seg_update(pidx[L[src]], -INF)
    last[pidx[L[src]]] = -INF

    heap = [(W[src], src)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
