            val, pi_1b = seg_argmin(1, lu_excl)
            if val >= d:
                break
            pi = pi_1b - 1
            target = None
            for ri_v, v in intervals_by[pi]:
                if pidx[R[v]] >= lu and not visited[v]:
                    nd = d + W[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(heap, (nd, v))
                    target = v
                    break
            if target is not None:
                visited[target] = True
                seg_update(pi_1b, W[target])
                last[pi_1b] = W[target]
            else:
                seg_update(pi_1b, INF)
                last[pi_1b] = INF
            processed += 1
        while processed < N:
            val, pi_1b = seg_argmin(lu, M)
            if val >= d:
                break
            pi = pi_1b - 1
            target = None
            for ri_v, v in intervals_by[pi]:
                if not visited[v]:
                    nd = d + W[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        heapq.heappush(heap, (nd, v))
                    target = v
                    break
            if target is not None:
                visited[target] = True
                seg_update(pi_1b, W[target])
                last[pi_1b] = W[target]
            else:
                seg_update(pi_1b, INF)
                last[pi_1b] = INF
            processed += 1

    results = []
    for s, t in queries:
        if dist[s] == INF or dist[t] == INF:
            results.append("-1")
