def solve():
    input = sys.stdin.buffer.read().decode()
    ptr = 0
    def next_int():
        nonlocal ptr
        while ptr < len(input) and input[ptr] <= ' ':
            ptr += 1
        val = 0
        sign = 1
        if input[ptr] == '-':
            sign = -1
            ptr += 1
        while ptr < len(input) and input[ptr] > ' ':
            val = val * 10 + (ord(input[ptr]) - 48)
            ptr += 1
        return val * sign

    N = next_int()
    W = [0] + [next_int() for _ in range(N)]
    intervals = []
    for i in range(N):
        L = next_int()
        R = next_int()
        intervals.append((L, R))

    # Compute interval graph components
    order = sorted(range(N), key=lambda i: (intervals[i][0], intervals[i][1]))
    comp = [-1] * N
    num_comps = 0
    cur_max_r = -1
    for idx in order:
        if idx == 0 or intervals[idx][0] > cur_max_r:
            num_comps += 1
            cur_max_r = intervals[idx][1]
        else:
            cur_max_r = max(cur_max_r, intervals[idx][1])
        comp[idx] = num_comps - 1

    Q = next_int()
    queries = []
    for _ in range(Q):
        s = next_int() - 1
        t = next_int() - 1
        queries.append((s, t))

    if num_comps >= 2:
        min_w_comp = [float('inf')] * num_comps
        for i in range(N):
            min_w_comp[comp[i]] = min(min_w_comp[comp[i]], W[i+1])
        global_min = min(W[1:])
        answers = []
        for s, t in queries:
            if comp[s] != comp[t]:
                answers.append(W[s+1] + W[t+1])
            else:
                c = comp[s]
                best = float('inf')
                for j in range(num_comps):
                    if j != c:
                        best = min(best, min_w_comp[j])
                answers.append(W[s+1] + W[t+1] + best)
        sys.stdout.write('\n'.join(map(str, answers)) + '\n')
    else:
        # Single component: BFS with caching
        sorted_by_start_pos = list(range(N))
        sorted_by_start_pos.sort(key=lambda i: intervals[i][0])
        sorted_by_end_pos = list(range(N))
        sorted_by_end_pos.sort(key=lambda i: intervals[i][1])

        def get_rightmost(s):
            rs = intervals[s][0]
            lo, hi = 0, N
            while lo < hi:
                mid = (lo + hi) // 2
                if intervals[sorted_by_end_pos[mid]][1] < rs:
                    lo = mid + 1
                else:
                    hi = mid
            return lo

        def get_leftmost(s):
            re = intervals[s][1]
            lo, hi = 0, N
            while lo < hi:
                mid = (lo + hi) // 2
                if intervals[sorted_by_start_pos[mid]][0] <= re:
                    lo = mid + 1
                else:
                    hi = mid
            return lo

        from collections import defaultdict
        class = [None] * N
        dist = [None] * N
        dist_type = [None] * (2 * N + 1)

        def bfs(s):
            if dist[s] is not None:
                return
            rm = get_rightmost(s)
            lm = get_leftmost(s)
            for i in sorted_by_end_pos[:rm]:
                class[i] = 'r'
            for i in sorted_by_start_pos[lm:]:
                class[i] = 'l'
            class[s] = -1
            dist_type[1] = 0
            for i in range(rm):
                dist_type[i * N] = 0
            for i in sorted_by_start_pos[lm:]:
                dist_type[i * N + 1] = 0
            dq = deque()
            dq.append((s, 0))
            dist[s] = 0
            while dq:
                u, d = dq.popleft()
                cp = class[u]
                if cp == 'r':
                    for i in range(N - 1, rm - 1, -1):
                        v = sorted_by_start_pos[i]
                        nd = d + W[v + 1]
                        key = v * N
                        if dist_type[key] is None or nd < dist_type[key]:
                            dist_type[key] = nd
                            dist[v] = nd
                            dq.append((v, nd))
                    for i in range(lm - 1, -1, -1):
                        v = sorted_by_end_pos[i]
                        nd = d + W[v + 1]
                        key = v * N + 1
                        if dist_type[key] is None or nd < dist_type[key]:
                            dist_type[key] = nd
                            dist[v] = nd
                            dq.append((v, nd))
                elif cp == 'l':
                    for i in range(rm):
                        v = sorted_by_end_pos[i]
                        nd = d + W[v + 1]
                        key = v * N
                        if dist_type[key] is None or nd < dist_type[key]:
                            dist_type[key] = nd
                            dist[v] = nd
                            dq.append((v, nd))
                    for i in range(N - 1, lm - 1, -1):
                        v = sorted_by_start_pos[i]
                        nd = d + W[v + 1]
                        key = v * N + 1
                        if dist_type[key] is None or nd < dist_type[key]:
                            dist_type[key] = nd
                            dist[v] = nd
                            dq.append((v, nd))
                else:
                    for i in range(N - 1, lm - 1, -1):
                        v = sorted_by_start_pos[i]
                        if v == s:
                            continue
                        nd = d + W[v + 1]
                        key = v * N + 1
                        if dist_type[key] is None or nd < dist_type[key]:
                            dist_type[key] = nd
                            dist[v] = nd
                            dq.append((v, nd))
                    for i in range(rm - 1, -1, -1):
                        v = sorted_by_end_pos[i]
                        if v == s:
                            continue
                        nd = d + W[v + 1]
                        key = v * N
                        if dist_type[key] is None or nd < dist_type[key]:
                            dist_type[key] = nd
                            dist[v] = nd
                            dq.append((v, nd))

        answers = []
        for s, t in queries:
            bfs(s)
            if dist[t] is not None:
                answers.append(dist[t] + W[s + 1])
            else:
                answers.append(-1)
        sys.stdout.write('\n'.join(map(str, answers)) + '\n')

