def count_snake_up_to(N):
    if N < 10:
        return 0
    s = str(N)
    m = len(s)
    a = [int(c) for c in s]

    total = 0
    for k in range(2, m):
        for d in range(1, 10):
            total += d ** (k - 1)

    d = a[0]
    for dp in range(1, d):
        total += dp ** (m - 1)

    count = 0
    tight = True
    for i in range(1, m):
        if a[i] >= d:
            count += d ** (m - i)
            tight = False
            break
        else:
            count += a[i] * (d ** (m - 1 - i))
    if tight:
        count += 1

    total += count
    return total

