def count_snake(N):
    if N < 10:
        return 0

    s = str(N)
    k = len(s)
    D = [int(c) for c in s]

    result = 0
    # Count numbers with fewer digits (2 to k-1 digits)
    for n in range(2, k):
        for d in range(1, 10):
            result += d ** (n - 1)

    # Count numbers with same number of digits
    # First digit from 1 to D[0]-1 (all remaining digits free in [0, d-1])
    for d in range(1, D[0]):
        result += d ** (k - 1)

    # First digit = D[0], process remaining digits with tight constraint
    d0 = D[0]
    tight = True
    for i in range(1, k):
        if tight:
            # Digits from 0 to min(D[i]-1, d0-1) at position i,
            # remaining positions free in [0, d0-1]
            free_digits = min(D[i], d0)
            if free_digits > 0:
                result += free_digits * (d0 ** (k - 1 - i))
            # Can we keep tight (choose D[i] itself)?
            if D[i] > d0 - 1:
                tight = False
    if tight:
        result += 1  # N itself is a valid snake number

    return result

