import sys
from functools import lru_cache

def count_snake(n):
    if n < 10:
        return 0

    s = str(n)
    length = len(s)
    digits = [int(c) for c in s]

    # Count snake numbers with fewer digits (2 to length-1 digits)
    total = 0
    for k in range(2, length):
        for d in range(1, 10):
            total += d ** (k - 1)

    # Count snake numbers with exactly 'length' digits that are <= n
    @lru_cache(maxsize=None)
    def dp(pos, first_digit, tight):
        if pos == length:
            return 1

        limit = digits[pos] if tight else 9
        result = 0
        for d in range(0, limit + 1):
            if pos == 0:
                if d == 0:
                    continue
                new_tight = 1 if (tight and d == limit) else 0
                result += dp(pos + 1, d, new_tight)
            else:
                if d < first_digit:
                    new_tight = 1 if (tight and d == limit) else 0
                    result += dp(pos + 1, first_digit, new_tight)

        return result

    total += dp(0, 0, 1)
    return total

def main():
    input_data = sys.stdin.read().split()
    L = int(input_data[0])
    R = int(input_data[1])
    print(count_snake(R) - count_snake(L - 1))

