from math import inf

def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    adj = [[] for _ in range(N)]
    for _ in range(N - 1):
        a, b = map(int, input().split())
        a -= 1; b -= 1
        adj[a].append(b); adj[b].append(a)

    if N < 5:
        print(-1)
        return

    NEG = -10**18
    parent = [-1] * N
    order = [0]
    parent[0] = -2
    for u in order:
        for v in adj[u]:
            if v != parent[u]:
                parent[v] = u
                order.append(v)

    # f[u][state][has4]
    f = [[[-inf, -inf] for _ in range(5)] for _ in range(N)]

    for u in reversed(order):
        children = [v for v in adj[u] if v != parent[u]]
        m = len(children)

        A, B, C, D = [], [], [], []
        for v in children:
            A.append(max(f[v][0][0], f[v][3][0], f[v][4][0]))
            B.append(max(f[v][0][1], f[v][3][1], f[v][4][1]))
            C.append(max(f[v][1][0], f[v][2][0]))
            D.append(max(f[v][1][1], f[v][2][1]))

        sumA = sum(A)

        def zero_conn_has4():
            """Best has4 value when 0 children are connected"""
            if m == 0:
                return NEG
            if all(b == NEG for b in B):
                return NEG
            mx = max(A)
            sw = sumA - mx
            if any(a > b for a, b in zip(A, B)):
                return sw + max(B)
            return sumA + max(b - a for a, b in zip(A, B))

        zc = zero_conn_has4()
        f[u][0][0] = sumA
        f[u][0][1] = zc
        f[u][1][0] = 1 + sumA
        f[u][1][1] = 1 + zc if zc > NEG else NEG

        for k, state in [(1, 3), (3, 2), (4, 4)]:
            if m < k:
                continue
            # no4: top k of (C-A)
            g_no = []
            for i in range(m):
                if C[i] > NEG and A[i] > NEG:
                    g_no.append(C[i] - A[i])
                else:
                    g_no.append(NEG)
            vn = sorted([g for g in g_no if g > NEG], reverse=True)
            if len(vn) >= k:
                f[u][state][0] = 1 + sumA + sum(vn[:k])

            # has4
            best = NEG
            # Case 1: a connected child j uses D[j]
            for j in range(m):
                if D[j] <= NEG:
                    continue
                others = [g_no[i] for i in range(m) if i != j and g_no[i] > NEG]
                others.sort(reverse=True)
                if k - 1 == 0:
                    val = D[j] + sumA - A[j]
                elif len(others) >= k - 1:
                    val = D[j] + sumA - A[j] + sum(others[:k-1])
                else:
                    continue
                if val > best:
                    best = val
            # Case 2: non-connected child provides has4
            g_c = []
            for i in range(m):
                if C[i] > NEG and A[i] > NEG:
                    g_c.append((C[i] - A[i], i))
                else:
                    g_c.append((NEG, i))
            valid = [(g, i) for g, i in g_c if g > NEG]
            if len(valid) >= k:
                valid.sort(key=lambda x: -x[0])
                topk_set = set(i for _, i in valid[:k])
                stk = sum(g for g, _ in valid[:k])
                for i in range(m):
                    if i not in topk_set and B[i] > NEG:
                        val = sumA + stk + B[i] - A[i]
                        if val > best:
                            best = val
            f[u][state][1] = 1 + best if best > NEG else NEG

    ans = max(f[0][3][1], f[0][4][1])
    print(ans if ans >= 0 else -1)

solve()

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG_INF = float('-inf')
        dp = [[NEG_INF] * (k + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            dp[i][0] = 0

        for j in range(1, k + 1):
            best = NEG_INF
            for i in range(j * m, n + 1):
                s = i - m
                if dp[s][j - 1] != NEG_INF:
                    best = max(best, dp[s][j - 1] - prefix[s])
                if best != NEG_INF:
                    dp[i][j] = max(dp[i - 1][j], prefix[i] + best)
                else:
                    dp[i][j] = dp[i - 1][j]

        return dp[n][k]

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG_INF = float('-inf')

        # dp_prev[s] = max sum using (j-1) subarrays from first s elements
        dp_prev = [NEG_INF] * (n + 1)
        dp_prev[0] = 0

        for j in range(1, k + 1):
            dp_curr = [NEG_INF] * (n + 1)
            best = NEG_INF
            for i in range(j * m, n + 1):
                # New candidate s = i - m becomes available
                s = i - m
                if s >= (j - 1) * m and dp_prev[s] != NEG_INF:
                    best = max(best, dp_prev[s] - prefix[s])

                if best != NEG_INF:
                    dp_curr[i] = max(dp_curr[i - 1], prefix[i] + best)
                else:
                    dp_curr[i] = dp_curr[i - 1]

            dp_prev = dp_curr

        return dp_prev[n]

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        NEG_INF = float('-inf')
        # dp[j][i] = max sum of j non-overlapping subarrays (each len >= m) from first i elements
        dp = [[NEG_INF] * (n + 1) for _ in range(k + 1)]
        for i in range(n + 1):
            dp[0][i] = 0

        for j in range(1, k + 1):
            best = NEG_INF
            for i in range(j * m, n + 1):
                # s = i - m is the new start position that becomes available
