            for i in range(1, n + 1):
                # Option 1: don't use position i-1 (extend previous)
                if i > 1 and i >= j * m:
                    if dp[i - 1][j] > dp[i][j]:
                        dp[i][j] = dp[i - 1][j]

                # Add new candidate s = i - m to running max
