                    val = dp[s][j - 1] - prefix[s]
                    if val > running_max:
                        running_max = val

                # Option 2: end j-th subarray at position i-1
                if i >= j * m and running_max > NEG_INF:
                    candidate = prefix[i] + running_max
                    if candidate > dp[i][j]:
                        dp[i][j] = candidate

        return dp[n][k]

