class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(a, b, k):
            a_prime = min(a, k)
            if a_prime == 0:
                return 0
            if k <= b:
                return a_prime * k - a_prime * (a_prime - 1) // 2
            else:
                full = min(a_prime, k - b + 1)
                if full >= a_prime:
                    return a_prime * b
                else:
                    rem = a_prime - full
                    return full * b + rem * k - (full + a_prime - 1) * rem // 2

        # Sum of minimums: prev strictly less, next less or equal
        left = [1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] >= nums[i]:
                stack.pop()
            left[i] = i - stack[-1] if stack else i + 1
            stack.append(i)

        right = [1] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] > nums[i]:
                stack.pop()
            right[i] = stack[-1] - i if stack else n - i
            stack.append(i)

        total_min = 0
        for i in range(n):
            total_min += nums[i] * count_pairs(left[i], right[i], k)

        # Sum of maximums: prev strictly greater, next greater or equal
        left = [1] * n
        stack = []
        for i in range(n):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            left[i] = i - stack[-1] if stack else i + 1
            stack.append(i)

        right = [1] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] < nums[i]:
                stack.pop()
            right[i] = stack[-1] - i if stack else n - i
            stack.append(i)

        total_max = 0
        for i in range(n):
            total_max += nums[i] * count_pairs(left[i], right[i], k)

        return total_min + total_max

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_pairs(A, B, K):
            """Count pairs (a,b) with 0<=a<A, 0<=b<B, a+b<=K"""
            upper_a = min(A - 1, K)
            if upper_a < 0:
                return 0
            split = K - B + 1
            total = 0
            # Part 1: a from 0 to min(upper_a, split), each contributes B
            end1 = min(upper_a, split)
            if end1 >= 0:
                total += (end1 + 1) * B
            # Part 2: a from max(0, split+1) to upper_a, contributes (K+1-a)
            lo = max(0, split + 1)
            hi = upper_a
            if lo <= hi:
                cnt = hi - lo + 1
                total += cnt * (K + 1) - (lo + hi) * cnt // 2
            return total

        def compute(role):
            # role='min': prev strictly smaller, next smaller-or-equal
            # role='max': prev strictly greater, next greater-or-equal
            left = [0] * n
            right = [0] * n
            stack = []
            for i in range(n):
                while stack:
                    if role == 'min' and nums[stack[-1]] < nums[i]:
                        break
                    if role == 'max' and nums[stack[-1]] > nums[i]:
                        break
                    stack.pop()
                left[i] = i - stack[-1] if stack else i + 1
                stack.append(i)

            stack = []
            for i in range(n - 1, -1, -1):
                while stack:
                    if role == 'min' and nums[stack[-1]] <= nums[i]:
                        break
                    if role == 'max' and nums[stack[-1]] >= nums[i]:
                        break
                    stack.pop()
                right[i] = stack[-1] - i if stack else n - i
                stack.append(i)

            K = k - 1
            total = 0
            for i in range(n):
                total += nums[i] * count_pairs(left[i], right[i], K)
            return total

        return compute('min') + compute('max')

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_subarrays(L, R, M):
            """Count pairs (a,b) with 0<=a<L, 0<=b<R, a+b<=M"""
            if M < 0:
                return 0
            # Part 1: where M-a+1 >= R, i.e., a <= M-R+1, contribution is R each
            upper1 = min(L - 1, M, M - R + 1)
            part1 = 0
            if upper1 >= 0:
                part1 = (upper1 + 1) * R
            # Part 2: where M-a+1 < R, contribution is M-a+1
            start2 = max(0, M - R + 2)
            end2 = min(L - 1, M)
            part2 = 0
            if start2 <= end2:
                cnt = end2 - start2 + 1
                part2 = cnt * (2 * (M + 1) - start2 - end2) // 2
            return part1 + part2

        def sum_of_extremes(find_min):
            left = [0] * n
            right = [0] * n
            stack = []
            for i in range(n):
                if find_min:
                    while stack and nums[stack[-1]] >= nums[i]:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] <= nums[i]:
                        stack.pop()
                left[i] = i - stack[-1] if stack else i + 1
                stack.append(i)
            stack = []
            for i in range(n - 1, -1, -1):
                if find_min:
                    while stack and nums[stack[-1]] > nums[i]:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] < nums[i]:
                        stack.pop()
                right[i] = stack[-1] - i if stack else n - i
                stack.append(i)

            M = k - 1
            total = 0
            for i in range(n):
                total += nums[i] * count_subarrays(left[i], right[i], M)
            return total

        return sum_of_extremes(True) + sum_of_extremes(False)

