            left = [1] * n
            right = [1] * n

            # Compute left distances
            stack = []
            for i in range(n):
                while stack:
                    if is_min:
                        if nums[stack[-1]] < nums[i]:
                            break
                    else:
                        if nums[stack[-1]] > nums[i]:
                            break
                    stack.pop()
                left[i] = i - stack[-1] if stack else i + 1
                stack.append(i)

