        return compute_sum(True) + compute_sum(False)

import sys
from collections import Counter
from functools import lru_cache

MOD = 998244353

def main():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    S = input_data[1]

    # Precompute factorials up to N//2 + 1
    max_k = N // 2 + 2
    fact = [1] * (max_k + 1)
    for i in range(1, max_k + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (max_k + 1)
    inv_fact[max_k] = pow(fact[max_k], MOD - 2, MOD)
    for i in range(max_k - 1, -1, -1):
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD

    sys.setrecursionlimit(20000)

    def compute_type(s):
        if not s:
            return ()
        types = []
        i = 0
        while i < len(s):
            depth = 0
            j = i
            while j < len(s):
                if s[j] == '(':
                    depth += 1
                else:
                    depth -= 1
                if depth == 0:
                    break
                j += 1
            content = s[i + 1:j]
            types.append(compute_type(content))
            i = j + 1
        types.sort()
        return tuple(types)

    type_s = compute_type(S)

    @lru_cache(maxsize=None)
    def f(t):
        k = len(t)
        if k == 0:
            return 1
        cnt = Counter(t)
        result = fact[k]
        for c, nc in cnt.items():
            result = result * inv_fact[nc] % MOD
            result = result * pow(f(c), nc, MOD) % MOD
        return result

    print(f(type_s))

