                child_hashes = sorted(node_hash[c] for c in children)
                # Use a simple hash
                h = 0
                for ch in child_hashes:
                    h = (h * 1000003 + ch + 1) % (2**61 - 1)
                node_hash[i] = h

                hash_count = defaultdict(list)
                for c in children:
                    hash_count[node_hash[c]].append(c)

                total_prod = 1
                denom = 1
                for hkey, group in hash_count.items():
                    prod = 1
                    for c in group:
                        prod = prod * node_total[c] % MOD
                    total_prod = total_prod * prod % MOD
                    denom = denom * fact[len(group)] % MOD

                node_total[i] = total_prod

