MOD = 998244353

def mirror(s):
    return ''.join(')' if c == '(' else '(' for c in reversed(s))

def solve():
    data = sys.stdin.read().split()
    N = int(data[0])
    S = data[1].strip()

    max_n = N + 1
    fact = [1] * max_n
    for i in range(1, max_n):
        fact[i] = fact[i-1] * i % MOD

    fact_inv = [1] * max_n
    fact_inv[max_n-1] = pow(fact[max_n-1], MOD-2, MOD)
    for i in range(max_n-2, -1, -1):
        fact_inv[i] = fact_inv[i+1] * (i+1) % MOD

    def inv_fact(n):
        return fact_inv[n]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(s):
        if not s:
            return 1
        # Find top-level primitive components
        bal = 0
        n = len(s)
        primes = []
        start = 0
        for i in range(n):
            if s[i] == '(':
                bal += 1
            else:
                bal -= 1
            if bal == 0:
                primes.append(s[start:i+1])
                start = i + 1

        if len(primes) == 1:
            # Primitive: (A) -> answer is dfs(A)
            return dfs(primes[0][1:-1])

        # Multiple primitives: compute group sizes and interior answers
        groups = {}
        total_product = 1
        for p in primes:
            interior = p[1:-1]
            m = mirror(interior)
            if m < interior:
                canonical = m
            else:
                canonical = interior
            if canonical not in groups:
                groups[canonical] = 0
            groups[canonical] += 1
            total_product = total_product * dfs(interior) % MOD

        # Multinomial coefficient: k! / (c1! * c2! * ...)
        k = len(primes)
        result = fact[k]
        for c in groups.values():
            result = result * inv_fact(c) % MOD

        return total_product * result % MOD

    print(dfs(S))

