        valid = True
        for i in range(H):
            if sum(a[i]) % 2 != 0:
                valid = False
                break
        if valid:
            for j in range(W):
                s = 0
                for i in range(H):
                    s += a[i][j]
                if s % 2 != 0:
                    valid = False
                    break

        if not valid:
            results.append("0")
            continue

        b_cells = []
        for i in range(H):
            for j in range(W):
                if a[i][j] == 0:
                    b_cells.append((i, j))

        if not b_cells:
            results.append(str(pow(2, H + W - 1, MOD)))
            continue

        # pref_r[i][j] = (a[i][1] + a[i][2] + ... + a[i][j]) % 2
        pref_r = [[0] * W for _ in range(H)]
        for i in range(H):
            for j in range(1, W):
                pref_r[i][j] = (pref_r[i][j-1] + a[i][j]) & 1

        # pref_c[i][j] = (a[1][j] + a[2][j] + ... + a[i][j]) % 2
        pref_c = [[0] * W for _ in range(H)]
        for j in range(W):
            for i in range(1, H):
                pref_c[i][j] = (pref_c[i-1][j] + a[i][j]) & 1

        # For B cell (i,j): c0 XOR d0 = 1 XOR pref_r[i][j] XOR pref_c[i][j]
        i0, j0 = b_cells[0]
