def solve():
    input_data = sys.stdin.buffer.read().split()
    idx = 0
    T = int(input_data[idx]); idx += 1
    out = []

    for _ in range(T):
        H = int(input_data[idx]); W = int(input_data[idx+1]); idx += 2
        S = []
        for i in range(H):
            S.append(input_data[idx].decode()); idx += 1

        # Compute pr[i][j] = number of A's in row i from col 0 to j-1, mod 2
        pr = [[0] * W for _ in range(H)]
        for i in range(H):
            for j in range(1, W):
                pr[i][j] = pr[i][j-1] ^ (1 if S[i][j-1] == 'A' else 0)

        # Compute pc[i][j] = number of A's in col j from row 0 to i-1, mod 2
        pc = [[0] * W for _ in range(H)]
        for j in range(W):
            for i in range(1, H):
                pc[i][j] = pc[i-1][j] ^ (1 if S[i-1][j] == 'A' else 0)

        # Union-Find for H+W variables
        n = H + W
        parent = list(range(n))
        rank = [0] * n
        val = [0] * n  # val[x] = variable_x XOR variable_parent

        def find(x):
            if parent[x] != x:
                root = find(parent[x])
                val[x] ^= val[parent[x]]
                parent[x] = root
            return parent[x]

        def union(x, y, w):
            # Ensures variable_x XOR variable_y = w
            rx, ry = find(x), find(y)
            vx, vy = val[x], val[y]
            if rx == ry:
                return (vx ^ vy) == w
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
                vx, vy = vy, vx
            parent[ry] = rx
            val[ry] = vx ^ vy ^ w
            if rank[rx] == rank[ry]:
                rank[rx] += 1
            return True

        contradiction = False
        for i in range(H):
            for j in range(W):
                if S[i][j] == 'B':
                    d = 1 ^ pc[i][j] ^ pr[i][j]
                    if not union(i, H + j, d):
                        contradiction = True
                        break
            if contradiction:
                break

        if contradiction:
            out.append("0")
        else:
            comp = {}
            for i in range(H):
                r = find(i)
                comp.setdefault(r, 0)
                comp[r] += 1
            for j in range(W):
                r = find(H + j)
                comp.setdefault(r, 0)
                comp[r] += 1

            ans = 1
            MOD = 998244353
            for cnt in comp.values():
                ans = ans * pow(2, cnt - 1, MOD) % MOD
            out.append(str(ans))

    print('\n'.join(out))

