        # c1 != c2 always
        INF = float('inf')
        dp = [[INF] * 3 for _ in range(3)]

        for i in range(m):
            new_dp = [[INF] * 3 for _ in range(3)]
            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:
                        continue
                    best_prev = INF
                    for pc1 in range(3):
                        for pc2 in range(3):
                            if pc1 == pc2:
                                continue
                            if pc1 == c1 or pc2 == c2:
                                continue
                            best_prev = min(best_prev, dp[pc1][pc2])
                    if i == 0:
                        new_dp[c1][c2] = cost[i][c1] + cost[n - 1 - i][c2]
                    else:
                        if best_prev < INF:
                            new_dp[c1][c2] = cost[i][c1] + cost[n - 1 - i][c2] + best_prev
            dp = new_dp

        result = INF
        for c1 in range(3):
            for c2 in range(3):
                if c1 != c2:
                    result = min(result, dp[c1][c2])
        return result

