    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = float('inf')

        dp = [[INF] * 3 for _ in range(3)]

        for i in range(m):
            new_dp = [[INF] * 3 for _ in range(3)]
            for c1 in range(3):
                for c2 in range(3):
                    if c1 == c2:
                        continue
                    base = cost[i][c1] + cost[n - 1 - i][c2]
                    if i == 0:
                        new_dp[c1][c2] = base
                    else:
                        best = INF
                        for pc1 in range(3):
                            for pc2 in range(3):
                                if pc1 == pc2:
                                    continue
                                if pc1 == c1 or pc2 == c2:
                                    continue
                                best = min(best, dp[pc1][pc2])
                        new_dp[c1][c2] = base + best
            dp = new_dp

        return min(min(row) for row in dp)

