    n = len(string)
    for i in range(n):
        if string[i] != '[':
            continue
        depth = 0
        max_depth = 0
        for j in range(i, n):
            if string[j] == '[':
                depth += 1
            else:
                depth -= 1
            if depth < 0:
                break
            max_depth = max(max_depth, depth)
            if depth == 0:
                if max_depth >= 2:
